             ROUND(NVL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NULL THEN T.MDE ELSE 0 END),0)/10000,6), --在途
             ROUND(NVL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NULL THEN T.MDE ELSE 0 END),0)/10000,6), --在途
             ROUND(NVL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.MDTSNY IS NOT NULL THEN T.MDE ELSE 0 END),0)/10000,6), --准予
             ROUND(NVL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.MDTSNY IS NOT NULL THEN T.MDE ELSE 0 END),0)/10000,6), --准予
             ROUND(NVL(SUM(CASE WHEN T.CKRQ_1< LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='Y' THEN T.MDE ELSE 0 END),0)/10000,6), --不予
             ROUND(NVL(SUM(CASE WHEN T.CKRQ_1>=LD_THISYEAR AND TRIM(T.LCSLID_FS) IS NOT NULL AND T.BYTSBZ='Y' THEN T.MDE ELSE 0 END),0)/10000,6) --不予
        INTO LN_SBHS, LN_SB_CKE_HIS, LN_SB_CKE_CUR, 
             LN_SB_ZZS_HIS, LN_SB_ZZS_CUR, LN_ZT_ZZS_HIS, LN_ZT_ZZS_CUR, LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_BY_ZZS_HIS, LN_BY_ZZS_CUR,
             LN_SB_XFS_HIS, LN_SB_XFS_CUR, LN_ZT_XFS_HIS, LN_ZT_XFS_CUR, LN_SH_XFS_HIS, LN_SH_XFS_CUR, LN_BY_XFS_HIS, LN_BY_XFS_CUR
        FROM (SELECT B.DJXH,B.LCSLID,B.SBXH,B.CKRQ_1,B.MDTSNY,B.BYTSBZ,C.LCSLID_FS,
                     B.MYLAJ * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN 1  
                                    WHEN A.SNBL_MDTSE=0 THEN 1
                                    WHEN A.SNBL_MDTSE>0 AND B.BYTSBZ='Y' THEN 0
                                    ELSE 1 - A.SNBL_MDTSE / A.ZY_MDTSE 
                               END AS MYLAJ,
                     B.MDTSE * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_ZZSTSE/A.SB_MDTSE END)
                                                             ELSE (CASE WHEN A.ZY_MDTSE=0 THEN 1 ELSE A.ZY_ZZSTSE/A.ZY_MDTSE END) 
                               END --根据是否复审用申报数或复审数计算退税部分
                             * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN 1  
                                    WHEN A.SNBL_ZZSTSE=0 THEN 1 
                                    WHEN A.SNBL_ZZSTSE>0 AND B.BYTSBZ='Y' THEN 0
                                    ELSE 1 - A.SNBL_ZZSTSE / A.ZY_ZZSTSE 
                               END AS TSE,
                     B.MDTSE * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN (CASE WHEN A.SB_MDTSE=0 THEN 0 ELSE A.SB_MDSE/A.SB_MDTSE END)
                                                             ELSE (CASE WHEN A.ZY_MDTSE=0 THEN 0 ELSE A.ZY_MDSE/A.ZY_MDTSE END) 
                               END
                             * CASE WHEN TRIM(C.LCSLID_FS) IS NULL THEN 1  
                                    WHEN A.SNBL_MDSE=0 THEN 1 
                                    WHEN A.SNBL_MDSE>0 AND B.BYTSBZ='Y' THEN 0
                                    ELSE 1 - A.SNBL_MDSE / A.ZY_MDSE 
                               END AS MDE
                FROM TL_TSSH.CKTS_LC_SHXX A
               INNER JOIN TL_TSSH.CKTS_SB_MDT_CKMX B ON B.LCSLID=A.LCSLID AND B.CHBZ='N' AND B.CKTMSYWLXDMJH LIKE '%DWCB%'
                LEFT JOIN (SELECT DISTINCT LCSLID_FS FROM TL_TSSH.CKTS_LC_YWHZXX S) C ON C.LCSLID_FS=A.LCSLID_FS
               WHERE A.TSSWJG_DM=V_SWCODE
                 AND A.QDSJ<LD_NEXTMONTH
                 AND A.LCJSRQ>=LD_THISYEAR) T;

      INSERT INTO TJBB_DT_B02105 (SSNY, BBLC, SWJGDM, SBHS, 
                SBLJ_TSCKE_HIS, SBLJ_TSCKE_YEAR, SBLJ_TMSE_HIS,  SBLJ_TMSE_YEAR, 
                SHLJ_TMSE_HIS,  SHLJ_TMSE_YEAR, SHBY_TMSE_HIS,  SHBY_TMSE_YEAR, SHZT_TMSE_HIS,  SHZT_TMSE_YEAR, 
                SPTK_TKE_HIS,   SPTK_TKE_YEAR, YSGK_TKE, GKBL_TKE_HIS,   GKBL_TKE_YEAR)
         SELECT LC_THISMONTH, '09', V_SWCODE, LN_SBHS, 
                LN_SB_CKE_HIS, LN_SB_CKE_CUR, LN_SB_ZZS_HIS, LN_SB_ZZS_CUR, 
                LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_BY_ZZS_HIS, LN_BY_ZZS_CUR, LN_ZT_ZZS_HIS, LN_ZT_ZZS_CUR, 
                LN_SH_ZZS_HIS, LN_SH_ZZS_CUR, LN_SH_ZZS_HIS + LN_SH_ZZS_CUR, LN_SH_ZZS_HIS, LN_SH_ZZS_CUR
           FROM DUAL
          UNION ALL
         SELECT LC_THISMONTH, '10', V_SWCODE, 0, 
                0, 0, LN_SB_XFS_HIS, LN_SB_XFS_CUR, 
                LN_SH_XFS_HIS, LN_SH_XFS_CUR, LN_BY_XFS_HIS, LN_BY_XFS_CUR, LN_ZT_XFS_HIS, LN_ZT_XFS_CUR, 
                LN_SH_XFS_HIS, LN_SH_XFS_CUR, LN_SH_XFS_HIS + LN_SH_XFS_CUR, LN_SH_XFS_HIS, LN_SH_XFS_CUR
           FROM DUAL;
      COMMIT;
    END;

