prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03102_CSH_NEW
/*************************************************
 * 浙江省办理出口退税累计趋势图（全部重新统计）
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY    IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LD_SYSDATE       DATE;
  LC_THISMONTH     VARCHAR2(6);
  LD_THISYEAR      DATE;
  LD_NEXTMONTH     DATE;
  LD_LASTYEAR      DATE;

  LC_THISYEAR      VARCHAR2(4);--当年
  LC_LASTYEAR      VARCHAR2(4);--上年
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';
  
  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=TRUNC(SYSDATE,'MM');
  END IF;
  LC_THISMONTH :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LD_THISYEAR  :=TRUNC(LD_SYSDATE,'YY');
  LD_NEXTMONTH :=TRUNC(ADD_MONTHS(LD_SYSDATE,1),'MM');
  LD_LASTYEAR  :=TRUNC(ADD_MONTHS(LD_SYSDATE,-12),'YY');

  LC_THISYEAR    :=TO_CHAR(LD_SYSDATE,'YYYY');
  LC_LASTYEAR    :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYY');
  
  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03102 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;
  
  --1、制表
  BEGIN
    --1.1 本年数
    --1.1.1 生产企业
    INSERT INTO TJBB_DT_B03102 (SSNY,BBLC,SWJGDM,
           JAN,FEB,MAR,APR,MAY,JUN,JUL,AUG,SEP,OCT,NOV,DEC,
           JAN_HZ,FEB_HZ,MAR_HZ,APR_HZ,MAY_HZ,JUN_HZ,JUL_HZ,AUG_HZ,SEP_HZ,OCT_HZ,NOV_HZ,DEC_HZ)
    WITH TSFN AS (SELECT TO_CHAR(T.RKRQ,'YYYYMM') AS FNMONTH, NVL(ROUND(SUM(T.SJJE)/10000,0),0) AS FNSE
                    FROM FG_CKTSFN_HXZG T
                    LEFT JOIN TL_TSSH.GLXT_BB_SHXT_DJXX R ON R.DJXH_JS=T.DJXH
                   WHERE T.SKSSSWJG_DM=V_SWCODE
                     AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
                     AND T.YWHZBUUID IS NULL
                     AND R.JSMODE='1'
                   GROUP BY TO_CHAR(T.RKRQ,'YYYYMM')),
         TSTK AS (SELECT TO_CHAR(S.XHRQ_TK,'YYYYMM') AS TKMONTH, NVL(ROUND(SUM(S.GKBL_ZZSTSE+S.GKBL_XFSTSE)/10000,0),0) AS TKSE
                    FROM TL_TSSH.CKTS_LC_SEHZXX S
                    LEFT JOIN TL_TSSH.GLXT_BB_SHXT_DJXX R ON R.DJXH_JS=S.DJXH
                   WHERE S.CKTMSJHSSSWJGDM=V_SWCODE
                     AND S.XHRQ_TK>=LD_THISYEAR AND S.XHRQ_TK<LD_NEXTMONTH
                     AND R.JSMODE='1'
                   GROUP BY TO_CHAR(S.XHRQ_TK,'YYYYMM'))
    SELECT LC_THISMONTH,'01',V_SWCODE,
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'01' AND LC_THISYEAR||'01'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'02' AND LC_THISYEAR||'02'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'03' AND LC_THISYEAR||'03'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'04' AND LC_THISYEAR||'04'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'05' AND LC_THISYEAR||'05'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'06' AND LC_THISYEAR||'06'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'07' AND LC_THISYEAR||'07'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'08' AND LC_THISYEAR||'08'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'09' AND LC_THISYEAR||'09'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'10' AND LC_THISYEAR||'10'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'11' AND LC_THISYEAR||'11'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'12' AND LC_THISYEAR||'12'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'01' AND LC_THISYEAR||'01'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'02' AND LC_THISYEAR||'02'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'03' AND LC_THISYEAR||'03'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'04' AND LC_THISYEAR||'04'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'05' AND LC_THISYEAR||'05'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'06' AND LC_THISYEAR||'06'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'07' AND LC_THISYEAR||'07'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'08' AND LC_THISYEAR||'08'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'09' AND LC_THISYEAR||'09'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'10' AND LC_THISYEAR||'10'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'11' AND LC_THISYEAR||'11'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'12' AND LC_THISYEAR||'12'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END)
      FROM TSTK
      LEFT JOIN TSFN ON TSFN.FNMONTH = TSTK.TKMONTH;
    COMMIT;

    --1.1.2 外贸企业
    INSERT INTO TJBB_DT_B03102 (SSNY,BBLC,SWJGDM,
           JAN,FEB,MAR,APR,MAY,JUN,JUL,AUG,SEP,OCT,NOV,DEC,
           JAN_HZ,FEB_HZ,MAR_HZ,APR_HZ,MAY_HZ,JUN_HZ,JUL_HZ,AUG_HZ,SEP_HZ,OCT_HZ,NOV_HZ,DEC_HZ)
    WITH TSFN AS (SELECT TO_CHAR(T.RKRQ,'YYYYMM') AS FNMONTH, NVL(ROUND(SUM(T.SJJE)/10000,0),0) AS FNSE
                    FROM FG_CKTSFN_HXZG T
                    LEFT JOIN TL_TSSH.GLXT_BB_SHXT_DJXX R ON R.DJXH_JS=T.DJXH
                   WHERE T.SKSSSWJG_DM=V_SWCODE
                     AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
                     AND T.YWHZBUUID IS NULL
                     AND (R.JSMODE IS NULL OR R.JSMODE<>'1')
                   GROUP BY TO_CHAR(T.RKRQ,'YYYYMM')),
         TSTK AS (SELECT TO_CHAR(S.XHRQ_TK,'YYYYMM') AS TKMONTH, NVL(ROUND(SUM(S.GKBL_ZZSTSE+S.GKBL_XFSTSE)/10000,0),0) AS TKSE
                    FROM TL_TSSH.CKTS_LC_SEHZXX S
                    LEFT JOIN TL_TSSH.GLXT_BB_SHXT_DJXX R ON R.DJXH_JS=S.DJXH
                   WHERE S.CKTMSJHSSSWJGDM=V_SWCODE
                     AND S.XHRQ_TK>=LD_THISYEAR AND S.XHRQ_TK<LD_NEXTMONTH
                     AND (R.JSMODE IS NULL OR R.JSMODE<>'1')
                   GROUP BY TO_CHAR(S.XHRQ_TK,'YYYYMM'))
    SELECT LC_THISMONTH,'02',V_SWCODE,
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'01' AND LC_THISYEAR||'01'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'02' AND LC_THISYEAR||'02'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'03' AND LC_THISYEAR||'03'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'04' AND LC_THISYEAR||'04'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'05' AND LC_THISYEAR||'05'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'06' AND LC_THISYEAR||'06'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'07' AND LC_THISYEAR||'07'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'08' AND LC_THISYEAR||'08'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'09' AND LC_THISYEAR||'09'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'10' AND LC_THISYEAR||'10'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'11' AND LC_THISYEAR||'11'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'12' AND LC_THISYEAR||'12'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'01' AND LC_THISYEAR||'01'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'02' AND LC_THISYEAR||'02'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'03' AND LC_THISYEAR||'03'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'04' AND LC_THISYEAR||'04'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'05' AND LC_THISYEAR||'05'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'06' AND LC_THISYEAR||'06'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'07' AND LC_THISYEAR||'07'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'08' AND LC_THISYEAR||'08'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'09' AND LC_THISYEAR||'09'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'10' AND LC_THISYEAR||'10'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'11' AND LC_THISYEAR||'11'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'12' AND LC_THISYEAR||'12'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END)
      FROM TSTK
      LEFT JOIN TSFN ON TSFN.FNMONTH = TSTK.TKMONTH;
    COMMIT;
    
    --1.2 上年数
    --1.2.1 生产企业
    INSERT INTO TJBB_DT_B03102 (SSNY,BBLC,SWJGDM,
           JAN,FEB,MAR,APR,MAY,JUN,JUL,AUG,SEP,OCT,NOV,DEC,
           JAN_HZ,FEB_HZ,MAR_HZ,APR_HZ,MAY_HZ,JUN_HZ,JUL_HZ,AUG_HZ,SEP_HZ,OCT_HZ,NOV_HZ,DEC_HZ)
    WITH TSFN AS (SELECT TO_CHAR(T.RKRQ,'YYYYMM') AS FNMONTH, NVL(ROUND(SUM(T.SJJE)/10000,0),0) AS FNSE
                    FROM FG_CKTSFN_HXZG T
                    LEFT JOIN TL_TSSH.GLXT_BB_SHXT_DJXX R ON R.DJXH_JS=T.DJXH
