prompt
prompt Creating procedure PRO_TJBB_DT_B03112_CSH_NEW
prompt =============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03112_CSH_NEW
/*************************************************
 * 浙江省对美出口商品分布情况统计表
 * 与03104的区别，退税额改为退免税额，出口国限定为美国
 * 20210205，金额栏保留整数，比率保留小数点后1位
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LC_THISMONTH     VARCHAR2(6);--当月
  LC_THISYEAR      VARCHAR2(6);--当年1月
  LC_LASTMONTH     VARCHAR2(6);--上年同期
  LC_LASTYEAR      VARCHAR2(6);--上年1月
  
  LN_CKE_THIS      NUMBER(16,4);--本年出口额合计
  LN_TSE_THIS      NUMBER(16,4);--本年退税额合计
  LN_CKE_LAST      NUMBER(16,4);--上年出口额合计
  LN_TSE_LAST      NUMBER(16,4);--上年退税额合计
  LC_SQL_UPDATEHZ  VARCHAR2(4000);
  LD_SYSDATE       DATE;
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=SYSDATE;
  END IF;
  
  LC_THISMONTH   :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LC_THISYEAR    :=TO_CHAR(LD_SYSDATE,'YYYY')||'01';
  LC_LASTMONTH   :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYYMM');
  LC_LASTYEAR    :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYY')||'01';
  
  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03112 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、计算并插入本年明细
  BEGIN
    INSERT INTO TJBB_DT_B03112 (SSNY,BBLC,SWJGDM,SPDLDM,SPDL,SPMC,CKE_YEAR,TSE_YEAR,CKE_YEAR_LAST,TSE_YEAR_LAST)
      WITH THISYEAR AS (SELECT XMFL, SUM(USD_AMT_USA) AS USD_AMT, SUM(TS_AMT_USA) AS TS_AMT
                          FROM TL_TSSH.TJBB_FHXX_CMCODE
                         WHERE SWCODE=V_SWCODE 
                           AND SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH
                         GROUP BY XMFL),
           LASTYEAR AS (SELECT XMFL, SUM(USD_AMT_USA) AS USD_AMT, SUM(TS_AMT_USA) AS TS_AMT
                          FROM TL_TSSH.TJBB_FHXX_CMCODE
                         WHERE SWCODE=V_SWCODE 
                           AND SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH
                         GROUP BY XMFL)
    SELECT LC_THISMONTH, 1+ ROW_NUMBER() OVER (ORDER BY SUM(NVL(C.USD_AMT,0)) DESC,SUM(NVL(D.USD_AMT,0)) DESC) AS BBLC, V_SWCODE, 
           A.SPML, A.MLDM, A.MLMC, 
           ROUND(SUM(C.USD_AMT)/10000,0), ROUND(SUM(C.TS_AMT)/10000,0), ROUND(SUM(D.USD_AMT)/10000,0), ROUND(SUM(D.TS_AMT)/10000,0)
      FROM DM_SPML A
     INNER JOIN DM_SPFL B ON A.SPML=B.SPML
      LEFT JOIN THISYEAR C ON C.XMFL = B.SPDL
      LEFT JOIN LASTYEAR D ON D.XMFL = B.SPDL
      GROUP BY A.SPML, A.MLDM, A.MLMC;
    COMMIT;
    
    UPDATE TJBB_DT_B03112
       SET BBLC = '0'||BBLC
     WHERE LENGTH(BBLC)<2;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;
  
  --2、计算并插入合计数
  BEGIN
    SELECT SUM(CKE_YEAR), SUM(TSE_YEAR), SUM(CKE_YEAR_LAST), SUM(TSE_YEAR_LAST)
      INTO LN_CKE_THIS, LN_TSE_THIS, LN_CKE_LAST, LN_TSE_LAST
      FROM TJBB_DT_B03112
     WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    
    INSERT INTO TJBB_DT_B03112 (SSNY,BBLC,SWJGDM,SPDLDM,SPDL,SPMC,CKE_YEAR,TSE_YEAR, CKE_YEAR_LAST, TSE_YEAR_LAST)
    SELECT LC_THISMONTH, '01', V_SWCODE,
           'HJ', '', '合计',
           LN_CKE_THIS, LN_TSE_THIS, LN_CKE_LAST, LN_TSE_LAST
      FROM DUAL;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;
  
  --3、同比计算
  BEGIN
    UPDATE TJBB_DT_B03112
       SET CKE_TB = CASE WHEN NVL(CKE_YEAR_LAST,0)=0 THEN NULL ELSE ROUND(100 * CKE_YEAR / CKE_YEAR_LAST -100,1) END,
           TSE_TB = CASE WHEN NVL(TSE_YEAR_LAST,0)=0 THEN NULL ELSE ROUND(100 * TSE_YEAR / TSE_YEAR_LAST -100,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --4、占比计算
  BEGIN
    UPDATE TJBB_DT_B03112 T
       SET CKE_ZB = CASE WHEN NVL(LN_CKE_THIS,0)=0 THEN NULL ELSE ROUND(100 * CKE_YEAR / LN_CKE_THIS,1) END,
           TSE_ZB = CASE WHEN NVL(LN_TSE_THIS,0)=0 THEN NULL ELSE ROUND(100 * TSE_YEAR / LN_TSE_THIS,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --5、汇总栏初始化
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B03112 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03112' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_TJBB_DT_B03113_CSH_NEW
prompt =============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03113_CSH_NEW
/*************************************************
 * 浙江省对美主要出口企业情况表
 * 20210205，金额栏保留整数，比率保留小数点后1位
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LC_THISMONTH     VARCHAR2(6);--当月
  LC_THISYEAR      VARCHAR2(6);--当年首月
  LC_LASTMONTH     VARCHAR2(6);--上年同期
  LC_LASTYEAR      VARCHAR2(6);--上年首月
  LC_SQL_UPDATEHZ  VARCHAR2(4000);
  LD_SYSDATE       DATE;
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=SYSDATE;
  END IF;

  LC_THISMONTH   :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LC_THISYEAR    :=TO_CHAR(LD_SYSDATE,'YYYY')||'01';
  LC_LASTMONTH   :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYYMM');
  LC_LASTYEAR    :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYY')||'01';

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03113 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、本年前50名当年数据与上年同期数据
  BEGIN
    INSERT INTO TJBB_DT_B03113 (SSNY,BBLC,SWJGDM,CPCODE,QYHGDM,QYMC,JSMODE,JSMODEMC,
                                USA_CKE_YEAR,CKE_YEAR,USA_TMSE_YEAR,TMSE_YEAR,PM,
                                USA_CKE_YEAR_LAST,CKE_YEAR_LAST,USA_TMSE_YEAR_LAST,TMSE_YEAR_LAST)
      WITH THISYEAR AS (SELECT A.CPCODE, A.QYHGDM, A.NSRMC, A.JSMODE,
                               SUM(B.USD_AMT_USA)/10000 AS USD_AMT_USA, SUM(B.USD_AMT_ALL)/10000 AS USD_AMT_ALL,
                               SUM(B.TS_AMT_USA)/10000 AS TSE_AMT_USA, SUM(B.TS_AMT_ALL)/10000 AS TSE_AMT_ALL,
                               ROW_NUMBER() OVER (PARTITION BY A.JSMODE ORDER BY SUM(B.USD_AMT_USA) DESC) AS PM
                          FROM TL_TSSH.GLXT_BB_SHXT_DJXX A, TL_TSSH.TJBB_FHXX_CPCODE B
                         WHERE A.SWJGDM=V_SWCODE 
                           AND B.SWCODE=V_SWCODE 
                           AND SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH
                           AND B.XMFL=A.CPCODE
                           AND A.JSMODE IN ('1','2')
                         GROUP BY A.CPCODE, A.QYHGDM, A.NSRMC, A.JSMODE),
           LASTYEAR AS (SELECT XMFL, SUM(USD_AMT_USA)/10000 AS USD_AMT_USA, SUM(USD_AMT_ALL)/10000 AS USD_AMT_ALL,
                               SUM(TS_AMT_USA)/10000 AS TSE_AMT_USA, SUM(TS_AMT_ALL)/10000 AS TSE_AMT_ALL
                          FROM TL_TSSH.TJBB_FHXX_CPCODE
                         WHERE SWCODE=V_SWCODE 
                           AND SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH
                         GROUP BY XMFL)
    SELECT LC_THISMONTH, A.JSMODE||CASE WHEN A.PM<10 THEN '0' ELSE '' END||A.PM, V_SWCODE,
           A.CPCODE, A.QYHGDM, A.NSRMC, A.JSMODE, CASE WHEN A.JSMODE='1' THEN '生产' ELSE '外贸' END,
           ROUND(A.USD_AMT_USA,0), ROUND(A.USD_AMT_ALL,0), ROUND(A.TSE_AMT_USA,0), ROUND(A.TSE_AMT_ALL,0), A.PM,
           ROUND(B.USD_AMT_USA,0), ROUND(B.USD_AMT_ALL,0), ROUND(B.TSE_AMT_USA,0), ROUND(B.TSE_AMT_ALL,0)
      FROM THISYEAR A
      LEFT JOIN LASTYEAR B ON B.XMFL = A.CPCODE
     WHERE PM<=50
       AND A.USD_AMT_USA>0
    ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --2、同比计算
  BEGIN
    UPDATE TJBB_DT_B03113
       SET USA_CKE_TB  = CASE WHEN NVL(USA_CKE_YEAR_LAST,0)=0 THEN NULL ELSE ROUND(100 * USA_CKE_YEAR / USA_CKE_YEAR_LAST -100,1) END,
           CKE_TB  = CASE WHEN NVL(CKE_YEAR_LAST,0)=0 THEN NULL ELSE ROUND(100 * CKE_YEAR / CKE_YEAR_LAST -100,1) END,
           USA_TMSE_TB = CASE WHEN NVL(USA_TMSE_YEAR_LAST,0)=0 THEN NULL ELSE ROUND(100 * USA_TMSE_YEAR / USA_TMSE_YEAR_LAST -100,1) END,
           TMSE_TB = CASE WHEN NVL(TMSE_YEAR_LAST,0)=0 THEN NULL ELSE ROUND(100 * TMSE_YEAR / TMSE_YEAR_LAST -100,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --3、占比计算
  BEGIN
    UPDATE TJBB_DT_B03113 T
       SET T.CKE_YEAR_ZB = CASE WHEN NVL(CKE_YEAR,0)=0 THEN NULL ELSE ROUND(100 * USA_CKE_YEAR / CKE_YEAR,1) END,
           T.CKE_YEAR_ZB_LAST = CASE WHEN NVL(CKE_YEAR_LAST,0)=0 THEN NULL ELSE ROUND(100 * USA_CKE_YEAR_LAST / CKE_YEAR_LAST,1) END,
           T.TMSE_YEAR_ZB = CASE WHEN NVL(TMSE_YEAR,0)=0 THEN NULL ELSE ROUND(100 * USA_TMSE_YEAR / TMSE_YEAR,1) END,
           T.TMSE_YEAR_ZB_LAST = CASE WHEN NVL(TMSE_YEAR_LAST,0)=0 THEN NULL ELSE ROUND(100 * USA_TMSE_YEAR_LAST / TMSE_YEAR_LAST,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --4、汇总栏初始化
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B03113 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03113' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_TJBB_DT_B03114_CSH_NEW
prompt =============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03114_CSH_NEW
/*************************************************
 * 对“一带一路”国家出口退（免）税情况统计表
 * 表结构与浙江省分出口市场统计表一样，算法条件有变化
 * 20210205，金额栏保留整数，比率保留小数点后1位
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LC_THISMONTH     VARCHAR2(6);--当月
  LC_THISYEAR      VARCHAR2(6);--当年1月
  LC_LASTMONTH     VARCHAR2(6);--上年同期
  LC_LASTYEAR      VARCHAR2(6);--上年1月
  
  LN_CKE_HJ        NUMBER(16,4);--出口额合计
  LN_TSE_HJ        NUMBER(16,4);--退税额合计
  LN_CKE_HJ_LAST   NUMBER(16,4);--出口额合计
  LN_TSE_HJ_LAST   NUMBER(16,4);--退税额合计
  LN_CKE_OTHER     NUMBER(16,4);--出口额合计
  LN_TSE_OTHER     NUMBER(16,4);--退税额合计
  LN_CKE_OTHER_LAST     NUMBER(16,4);--出口额合计
  LN_TSE_OTHER_LAST     NUMBER(16,4);--退税额合计

  V_TEMP           NUMBER(10, 0) := 0;
  LC_SQL_UPDATEHZ  VARCHAR2(4000);
  LD_SYSDATE       DATE;
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=SYSDATE;
  END IF;
  
  LC_THISMONTH   :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LC_THISYEAR    :=TO_CHAR(LD_SYSDATE,'YYYY')||'01';
  LC_LASTMONTH   :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYYMM');
  LC_LASTYEAR    :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYY')||'01';

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03114_MID WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    DELETE FROM TJBB_DT_B03114 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、中间表数据计算
  BEGIN
    INSERT INTO TJBB_DT_B03114_MID (SWJGDM,SSNY,DMTYPE,GBDM,CKE_LJ,TSE_LJ,CKPM)
    SELECT V_SWCODE, LC_THISMONTH, 'BR', DQ_CODE, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
      FROM (SELECT A.DQ_CODE, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM DM_DQCODE A
             INNER JOIN DM_DQGROUP B ON A.DQ_CODE=B.DQ_CODE
              LEFT JOIN TL_TSSH.TJBB_FHXX_GBCODE C ON B.GB_CODE=C.XMFL AND C.SWCODE=V_SWCODE AND C.SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH
             WHERE A.DQ_TYPE='BR'
             GROUP BY A.DQ_CODE)
     UNION ALL
    SELECT V_SWCODE, LC_THISMONTH, 'GJ', XMFL, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
      FROM (SELECT C.XMFL, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM DM_DQCODE A
             INNER JOIN DM_DQGROUP B ON A.DQ_CODE=B.DQ_CODE
             INNER JOIN TL_TSSH.TJBB_FHXX_GBCODE C ON B.GB_CODE=C.XMFL AND C.SWCODE=V_SWCODE AND C.SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH
             WHERE A.DQ_TYPE='BR'
             GROUP BY C.XMFL);
    COMMIT;

    SELECT COUNT(1)
      INTO V_TEMP
      FROM TJBB_DT_B03114_MID
     WHERE SWJGDM=V_SWCODE AND SSNY=LC_LASTMONTH AND DMTYPE='GJ';
    IF V_TEMP = 0 THEN
      BEGIN
        DELETE FROM TJBB_DT_B03114_MID WHERE SWJGDM=V_SWCODE AND SSNY=LC_LASTMONTH;
        COMMIT;

        INSERT INTO TJBB_DT_B03114_MID (SWJGDM,SSNY,DMTYPE,GBDM,CKE_LJ,TSE_LJ,CKPM)
        SELECT V_SWCODE, LC_LASTMONTH, 'BR', DQ_CODE, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
          FROM (SELECT A.DQ_CODE, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
                  FROM DM_DQCODE A
                 INNER JOIN DM_DQGROUP B ON A.DQ_CODE=B.DQ_CODE
                  LEFT JOIN TL_TSSH.TJBB_FHXX_GBCODE C ON B.GB_CODE=C.XMFL AND C.SWCODE=V_SWCODE AND C.SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH
                 WHERE A.DQ_TYPE='BR'
                 GROUP BY A.DQ_CODE)
         UNION ALL
        SELECT V_SWCODE, LC_LASTMONTH, 'GJ', XMFL, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
          FROM (SELECT C.XMFL, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
                  FROM DM_DQCODE A
                 INNER JOIN DM_DQGROUP B ON A.DQ_CODE=B.DQ_CODE
                 INNER JOIN TL_TSSH.TJBB_FHXX_GBCODE C ON B.GB_CODE=C.XMFL AND C.SWCODE=V_SWCODE AND C.SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH
                 WHERE A.DQ_TYPE='BR'
                 GROUP BY C.XMFL);
        COMMIT;
      END;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --2、计算并插入区域情况及本年前10名明细及上年同期
  BEGIN
    INSERT INTO TJBB_DT_B03114 (SSNY,BBLC,SWJGDM,ITEM,CKE_USD,TMSE,CKE_USD_LAST,TMSE_LAST)
    SELECT LC_THISMONTH, '100', V_SWCODE, '区域情况', NULL, NULL, NULL, NULL
      FROM DUAL
     UNION ALL
    SELECT B.SSNY, CASE WHEN B.CKPM<10 THEN '10' ELSE '1' END || B.CKPM, B.SWJGDM, A.DQ_NAME, B.CKE_LJ, B.TSE_LJ, C.CKE_LJ, C.TSE_LJ
      FROM DM_DQCODE A
     INNER JOIN TJBB_DT_B03114_MID B ON A.DQ_CODE=B.GBDM AND B.SWJGDM=V_SWCODE AND B.SSNY=LC_THISMONTH AND B.DMTYPE='BR'
      LEFT JOIN TJBB_DT_B03114_MID C ON A.DQ_CODE=C.GBDM AND C.SWJGDM=V_SWCODE AND C.SSNY=LC_LASTMONTH AND C.DMTYPE='BR'
     WHERE A.DQ_TYPE='BR'
     UNION ALL
    SELECT LC_THISMONTH, '200', V_SWCODE, '10个主要国别情况', NULL, NULL, NULL, NULL
      FROM DUAL
     UNION ALL
    SELECT B.SSNY, CASE WHEN B.CKPM<10 THEN '20' ELSE '2' END || B.CKPM, B.SWJGDM, A.GB_NAME, B.CKE_LJ, B.TSE_LJ, C.CKE_LJ, C.TSE_LJ
      FROM DM_GBCODE A
     INNER JOIN TJBB_DT_B03114_MID B ON A.GB_CODE=B.GBDM AND B.SWJGDM=V_SWCODE AND B.SSNY=LC_THISMONTH AND B.DMTYPE='GJ'
      LEFT JOIN TJBB_DT_B03114_MID C ON A.GB_CODE=C.GBDM AND C.SWJGDM=V_SWCODE AND C.SSNY=LC_LASTMONTH AND C.DMTYPE='GJ'
     WHERE B.CKPM<=10;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --3、计算并插入合计数
  BEGIN
    SELECT SUM(CKE_LJ), SUM(TSE_LJ)
      INTO LN_CKE_HJ, LN_TSE_HJ
      FROM TJBB_DT_B03114_MID
     WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH AND DMTYPE='GJ';

    SELECT SUM(CKE_LJ), SUM(TSE_LJ)
      INTO LN_CKE_HJ_LAST, LN_TSE_HJ_LAST
      FROM TJBB_DT_B03114_MID
     WHERE SWJGDM=V_SWCODE AND SSNY=LC_LASTMONTH AND DMTYPE='GJ';

    INSERT INTO TJBB_DT_B03114 (SSNY,BBLC,SWJGDM,ITEM,CKE_USD,TMSE,CKE_USD_LAST,TMSE_LAST)
    SELECT LC_THISMONTH, '001', V_SWCODE, '“一带一路”沿线64国', LN_CKE_HJ, LN_TSE_HJ, LN_CKE_HJ_LAST, LN_TSE_HJ_LAST
      FROM DUAL;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  --4、同比计算
  BEGIN
    UPDATE TJBB_DT_B03114
       SET CKE_TB  = CASE WHEN NVL(CKE_USD_LAST,0)=0 THEN NULL ELSE ROUND(100 * CKE_USD / CKE_USD_LAST -100,1) END,
           TMSE_TB = CASE WHEN NVL(TMSE_LAST,0)=0    THEN NULL ELSE ROUND(100 * TMSE    / TMSE_LAST    -100,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --5、占比计算
  BEGIN
    UPDATE TJBB_DT_B03114 T
       SET CKE_ZB  = CASE WHEN NVL(LN_CKE_HJ,0)=0 THEN NULL ELSE ROUND(100 * CKE_USD / LN_CKE_HJ,1) END,
           TMSE_ZB = CASE WHEN NVL(LN_TSE_HJ,0)=0 THEN NULL ELSE ROUND(100 * TMSE / LN_TSE_HJ,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --6、汇总栏初始化
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B03114 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03114' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

