prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03117_CSH_NEW
/*************************************************
 * 启运港政策出口退税情况表
 * 202504，根据省局关注点全新设计，分出口电子信息（其中剔除市场采购）、申报、办理
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LD_SYSDATE       DATE;
  LC_THISMONTH     VARCHAR2(6);
  LD_THISYEAR      DATE;
  LD_NEXTMONTH     DATE;
  LC_SQL           VARCHAR2(4000);
  LC_SQL_UPDATEHZ  VARCHAR2(4000);
  LN_CK_HS         NUMBER(10);
  LN_CK_MY         NUMBER(18,6);
  LN_CK_RMB        NUMBER(18,6);
  LN_CK_HS_F1039   NUMBER(10);
  LN_CK_MY_F1039   NUMBER(18,6);
  LN_CK_RMB_F1039  NUMBER(18,6);
  LN_SB_HS         NUMBER(10);
  LN_SB_MY         NUMBER(18,6);
  LN_SB_JSJE       NUMBER(18,6);
  LN_SB_TMSE       NUMBER(18,6);
  LN_BL_HS         NUMBER(10);
  LN_BL_MY         NUMBER(18,6);
  LN_BL_JSJE       NUMBER(18,6);
  LN_BL_TMSE       NUMBER(18,6);
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';
  
  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=TRUNC(SYSDATE,'MM');
  END IF;
  LC_THISMONTH :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LD_THISYEAR  :=TRUNC(LD_SYSDATE,'YY');
  LD_NEXTMONTH :=TRUNC(ADD_MONTHS(LD_SYSDATE,1),'MM');

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03117 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、当月总数
  BEGIN
    SELECT COUNT(DISTINCT BGD.DJXH), NVL(ROUND(SUM(BGD.MYLAJ)/10000,6),0), NVL(ROUND(SUM(BGD.RMBLAJ)/10000,6),0),
           COUNT(DISTINCT CASE WHEN BGD.JGFS_DM='1039' THEN NULL ELSE BGD.DJXH END),
           NVL(ROUND(SUM(CASE WHEN BGD.JGFS_DM='1039' THEN 0 ELSE BGD.MYLAJ END)/10000,6),0),
           NVL(ROUND(SUM(CASE WHEN BGD.JGFS_DM='1039' THEN 0 ELSE BGD.RMBLAJ END)/10000,6),0)
      INTO LN_CK_HS, LN_CK_MY, LN_CK_RMB, LN_CK_HS_F1039, LN_CK_MY_F1039, LN_CK_RMB_F1039
      FROM TL_TSSH.CKTS_WBSJ_HG_BGD BGD
     WHERE BGD.TSSWJG_DM_1=V_SWCODE
       AND BGD.QYGBZ = 'Y'
       AND BGD.CKRQ_1>=LD_SYSDATE AND BGD.CKRQ_1<LD_NEXTMONTH;
    
    SELECT COUNT(DISTINCT DJXH), NVL(ROUND(SUM(MYLAJ)/10000,6),0), NVL(ROUND(SUM(JSJE)/10000,6),0), NVL(ROUND(SUM(TMSE)/10000,6),0)
      INTO LN_SB_HS, LN_SB_MY, LN_SB_JSJE, LN_SB_TMSE
      FROM (SELECT MDT.DJXH, MDT.MYLAJ, MDT.RMBLAJ AS JSJE, MDT.MDTSE AS TMSE
              FROM TL_TSSH.CKTS_SB_MDT_CKMX MDT
             WHERE MDT.TSSWJG_DM=V_SWCODE
               AND REGEXP_LIKE(MDT.CKTMSYWLXDMJH ,'^QYGTS')
               AND MDT.SBRQ>=LD_SYSDATE AND MDT.SBRQ<LD_NEXTMONTH
             UNION ALL
            SELECT MTS.DJXH, MTS.MYLAJ, MTS.JSJE, MTS.TSE AS TMSE
              FROM TL_TSSH.CKTS_SB_MTS_CKMX MTS
             WHERE MTS.TSSWJG_DM=V_SWCODE
               AND REGEXP_LIKE(MTS.CKTMSYWLXDMJH ,'^QYGTS')
               AND MTS.SBRQ>=LD_SYSDATE AND MTS.SBRQ<LD_NEXTMONTH
             UNION ALL
            SELECT WZF.DJXH, WZF.MYLAJ, WZF.JSJE, WZF.TSE AS TMSE
              FROM TL_TSSH.CKTS_SB_WZF_CKMX WZF
             WHERE WZF.TSSWJG_DM=V_SWCODE
               AND REGEXP_LIKE(WZF.CKTMSYWLXDMJH ,'^QYGTS')
               AND WZF.SBRQ>=LD_SYSDATE AND WZF.SBRQ<LD_NEXTMONTH) T;
    
    SELECT COUNT(DISTINCT DJXH), NVL(ROUND(SUM(MYLAJ)/10000,6),0), NVL(ROUND(SUM(JSJE)/10000,6),0), NVL(ROUND(SUM(TMSE)/10000,6),0)
      INTO LN_BL_HS, LN_BL_MY, LN_BL_JSJE, LN_BL_TMSE
      FROM (SELECT MDT.DJXH, MDT.MYLAJ, MDT.RMBLAJ AS JSJE, MDT.MDTSE AS TMSE
              FROM TL_TSSH.CKTS_SB_MDT_CKMX MDT
             WHERE MDT.TSSWJG_DM=V_SWCODE
               AND REGEXP_LIKE(MDT.CKTMSYWLXDMJH ,'^QYGTS')
               AND MDT.FSRQ>=LD_SYSDATE AND MDT.FSRQ<LD_NEXTMONTH
               AND NVL(MDT.BYBLBZ,'N')='N' AND NVL(MDT.BYTSBZ,'N')='N' AND MDT.SJLY='2'
             UNION ALL
            SELECT MTS.DJXH, MTS.MYLAJ, MTS.JSJE, MTS.TSE AS TMSE
              FROM TL_TSSH.CKTS_SB_MTS_CKMX MTS
             WHERE MTS.TSSWJG_DM=V_SWCODE
               AND REGEXP_LIKE(MTS.CKTMSYWLXDMJH ,'^QYGTS')
