  LC_THISYEAR    :=TO_CHAR(LD_SYSDATE,'YYYY');
  LC_LASTYEAR    :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYY');
  
  --0、清除原有制表数据，准备重新制表
  BEGIN
