    INSERT INTO TJBB_DT_B03102 (SSNY,BBLC,SWJGDM,
           JAN,FEB,MAR,APR,MAY,JUN,JUL,AUG,SEP,OCT,NOV,DEC,
           JAN_HZ,FEB_HZ,MAR_HZ,APR_HZ,MAY_HZ,JUN_HZ,JUL_HZ,AUG_HZ,SEP_HZ,OCT_HZ,NOV_HZ,DEC_HZ)
    WITH TSFN AS (SELECT TO_CHAR(T.RKRQ,'YYYYMM') AS FNMONTH, NVL(ROUND(SUM(T.SJJE)/10000,0),0) AS FNSE
                    FROM FG_CKTSFN_HXZG T
                    LEFT JOIN TL_TSSH.GLXT_BB_SHXT_DJXX R ON R.DJXH_JS=T.DJXH
                   WHERE ((V_SWCODE='13300000000'  AND (T.SKSSSWJG_DM IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                          (V_SWCODE<>'13300000000' AND (T.SKSSSWJG_DM IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
                     AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
                     AND T.YWHZBUUID IS NULL
                     AND R.JSMODE='1'
                   GROUP BY TO_CHAR(T.RKRQ,'YYYYMM')),
         TSTK AS (SELECT TO_CHAR(S.XHRQ_TK,'YYYYMM') AS TKMONTH, NVL(ROUND(SUM(S.GKBL_ZZSTSE+S.GKBL_XFSTSE)/10000,0),0) AS TKSE
                    FROM TL_TSSH.CKTS_LC_SEHZXX S
                    LEFT JOIN TL_TSSH.GLXT_BB_SHXT_DJXX R ON R.DJXH_JS=S.DJXH
                   WHERE ((V_SWCODE='13300000000'  AND (S.CKTMSJHSSSWJGDM IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                          (V_SWCODE<>'13300000000' AND (S.CKTMSJHSSSWJGDM IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
                     AND S.XHRQ_TK>=LD_THISYEAR AND S.XHRQ_TK<LD_NEXTMONTH
                     AND R.JSMODE='1'
                   GROUP BY TO_CHAR(S.XHRQ_TK,'YYYYMM'))
    SELECT LC_THISMONTH,'01',V_SWCODE,
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'01' AND LC_THISYEAR||'01'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
           SUM(CASE WHEN TSTK.TKMONTH<=LC_THISYEAR||'02' AND LC_THISYEAR||'02'<=V_SSNY THEN NVL(TSTK.TKSE,0) - NVL(TSFN.FNSE,0) ELSE 0 END),
