    SELECT LC_THISMONTH, '06', V_SWCODE, 
           SUM(JAN),SUM(FEB),SUM(MAR),SUM(APR),SUM(MAY),SUM(JUN),SUM(JUL),SUM(AUG),SUM(SEP),SUM(OCT),SUM(NOV),SUM(DEC),
           SUM(JAN_HZ),SUM(FEB_HZ),SUM(MAR_HZ),SUM(APR_HZ),SUM(MAY_HZ),SUM(JUN_HZ),SUM(JUL_HZ),SUM(AUG_HZ),SUM(SEP_HZ),SUM(OCT_HZ),SUM(NOV_HZ),SUM(DEC_HZ)
      FROM TJBB_DT_B03102
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH
       AND BBLC IN ('04','05');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;
  
  --2、同比
  BEGIN
    --生产
    INSERT INTO TJBB_DT_B03102 (SSNY,BBLC,SWJGDM,
