  --4、汇总栏初始化
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B03106 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03106' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_TJBB_DT_B03107_HZ_NEW
prompt ============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03107_HZ_NEW
/*************************************************
 * 浙江省出口退（免）税分类管理情况统计表（省、市局汇总）
 * 20210205，金额栏保留整数，比率保留小数点后1位
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LC_THISMONTH     VARCHAR2(6);--当月
  LC_THISYEAR      VARCHAR2(6);--当年1月
  LC_LASTMONTH     VARCHAR2(6);--上年同期
  LC_LASTYEAR      VARCHAR2(6);--上年1月
  
  LN_TSE_HJ        NUMBER(16,4);--退税额合计
  TSE_1_LAST       NUMBER(16,4);
  TSE_2_LAST       NUMBER(16,4);
  TSE_3_LAST       NUMBER(16,4);
  TSE_4_LAST       NUMBER(16,4);
  LC_SQL_UPDATEHZ  VARCHAR2(4000);
  LD_SYSDATE       DATE;
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=SYSDATE;
  END IF;
  
  LC_THISMONTH   :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LC_THISYEAR    :=TO_CHAR(LD_SYSDATE,'YYYY')||'01';
  LC_LASTMONTH   :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYYMM');
  LC_LASTYEAR    :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYY')||'01';

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03107 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、计算并插入本年明细
  BEGIN
    INSERT INTO TJBB_DT_B03107 (SSNY,BBLC,SWJGDM,SBHS_1,SBHS_2,SBHS_3,SBHS_4,TSE_1_LJ,TSE_2_LJ,TSE_3_LJ,TSE_4_LJ)
    WITH THISYEAR AS (SELECT A.XMFL, A.TS_AMT_ALL, NVL(B.FLGLCD,'C') AS FLGLCD_B, NVL(C.KZXX,'C') AS FLGLCD_C, 
                             ROW_NUMBER() OVER (PARTITION BY A.SWCODE,A.XMFL,A.SSNY,A.SBYWBDM ORDER BY C.ST_DATE DESC) AS RN
                        FROM TL_TSSH.TJBB_FHXX_CPCODE A
                        LEFT JOIN TL_TSSH.GLXT_BB_SHXT_DJXX B ON A.XMFL=B.CPCODE
                        LEFT JOIN TL_BJTS.GS_DJ_CKTMSDAB_KZ C ON A.XMFL=C.CPCODE AND C.KZLX='FLGLCD' AND C.FLAG='1' AND A.SSNY||'01' BETWEEN TO_CHAR(C.ST_DATE,'YYYYMMDD') AND TO_CHAR(C.END_DATE,'YYYYMMDD')
                       WHERE ((V_SWCODE='13300000000'  AND (A.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                              (V_SWCODE<>'13300000000' AND (A.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
                         AND A.SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH)
    SELECT LC_THISMONTH, '01', V_SWCODE, 
           COUNT(DISTINCT CASE WHEN FLGLCD_B='A' THEN XMFL ELSE NULL END),
           COUNT(DISTINCT CASE WHEN FLGLCD_B='B' THEN XMFL ELSE NULL END),
           COUNT(DISTINCT CASE WHEN FLGLCD_B='C' THEN XMFL ELSE NULL END),
           COUNT(DISTINCT CASE WHEN FLGLCD_B='D' THEN XMFL ELSE NULL END),
           ROUND(SUM(CASE WHEN FLGLCD_C='A' THEN TS_AMT_ALL ELSE 0 END)/10000,0),
           ROUND(SUM(CASE WHEN FLGLCD_C='B' THEN TS_AMT_ALL ELSE 0 END)/10000,0),
           ROUND(SUM(CASE WHEN FLGLCD_C='C' THEN TS_AMT_ALL ELSE 0 END)/10000,0),
           ROUND(SUM(CASE WHEN FLGLCD_C='D' THEN TS_AMT_ALL ELSE 0 END)/10000,0)
      FROM THISYEAR
     WHERE RN=1;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --2、更新地区名称
  BEGIN
    UPDATE TJBB_DT_B03107 T
       SET AREA=(SELECT S.SWJG_JC FROM DM_SWJG S WHERE S.SWJG_DM=T.SWJGDM)
     WHERE T.SWJGDM=V_SWCODE
       AND T.SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  --3、更新上年同期
  BEGIN
    WITH LASTYEAR AS (SELECT A.XMFL, A.TS_AMT_ALL, NVL(B.FLGLCD,'C') AS FLGLCD_B, NVL(C.KZXX,'C') AS FLGLCD_C, 
                             ROW_NUMBER() OVER (PARTITION BY A.SWCODE,A.XMFL,A.SSNY,A.SBYWBDM ORDER BY C.ST_DATE DESC) AS RN
                        FROM TL_TSSH.TJBB_FHXX_CPCODE A
                        LEFT JOIN TL_TSSH.GLXT_BB_SHXT_DJXX B ON A.XMFL=B.CPCODE
                        LEFT JOIN TL_BJTS.GS_DJ_CKTMSDAB_KZ C ON A.XMFL=C.CPCODE AND C.KZLX='FLGLCD' AND C.FLAG='1' AND A.SSNY||'01' BETWEEN TO_CHAR(C.ST_DATE,'YYYYMMDD') AND TO_CHAR(C.END_DATE,'YYYYMMDD')
                       WHERE ((V_SWCODE='13300000000'  AND (A.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                              (V_SWCODE<>'13300000000' AND (A.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
                         AND A.SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH)
    SELECT ROUND(SUM(CASE WHEN FLGLCD_C='A' THEN TS_AMT_ALL ELSE 0 END)/10000,0),
           ROUND(SUM(CASE WHEN FLGLCD_C='B' THEN TS_AMT_ALL ELSE 0 END)/10000,0),
           ROUND(SUM(CASE WHEN FLGLCD_C='C' THEN TS_AMT_ALL ELSE 0 END)/10000,0),
           ROUND(SUM(CASE WHEN FLGLCD_C='D' THEN TS_AMT_ALL ELSE 0 END)/10000,0)
      INTO TSE_1_LAST,TSE_2_LAST,TSE_3_LAST,TSE_4_LAST
      FROM LASTYEAR
     WHERE RN=1;
    UPDATE TJBB_DT_B03107 T
       SET (TSE_1_LJ_LAST,TSE_2_LJ_LAST,TSE_3_LJ_LAST,TSE_4_LJ_LAST) = (SELECT TSE_1_LAST,TSE_2_LAST,TSE_3_LAST,TSE_4_LAST FROM DUAL)
     WHERE T.SWJGDM=V_SWCODE
       AND T.SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  --4、同比计算
  BEGIN
    UPDATE TJBB_DT_B03107
       SET TSE_1_TB = CASE WHEN NVL(TSE_1_LJ_LAST,0)=0 THEN NULL ELSE ROUND(100 * TSE_1_LJ / TSE_1_LJ_LAST -100,1) END,
           TSE_2_TB = CASE WHEN NVL(TSE_2_LJ_LAST,0)=0 THEN NULL ELSE ROUND(100 * TSE_2_LJ / TSE_2_LJ_LAST -100,1) END,
           TSE_3_TB = CASE WHEN NVL(TSE_3_LJ_LAST,0)=0 THEN NULL ELSE ROUND(100 * TSE_3_LJ / TSE_3_LJ_LAST -100,1) END,
           TSE_4_TB = CASE WHEN NVL(TSE_4_LJ_LAST,0)=0 THEN NULL ELSE ROUND(100 * TSE_4_LJ / TSE_4_LJ_LAST -100,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --5、占比计算
  BEGIN
    SELECT TSE_1_LJ + TSE_2_LJ + TSE_3_LJ + TSE_4_LJ
      INTO LN_TSE_HJ
      FROM TJBB_DT_B03107
     WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    
    UPDATE TJBB_DT_B03107 T
       SET TSE_1_ZB = CASE WHEN NVL(LN_TSE_HJ,0)=0 THEN NULL ELSE ROUND(100 * TSE_1_LJ / LN_TSE_HJ,1) END,
           TSE_2_ZB = CASE WHEN NVL(LN_TSE_HJ,0)=0 THEN NULL ELSE ROUND(100 * TSE_2_LJ / LN_TSE_HJ,1) END,
           TSE_3_ZB = CASE WHEN NVL(LN_TSE_HJ,0)=0 THEN NULL ELSE ROUND(100 * TSE_3_LJ / LN_TSE_HJ,1) END,
           TSE_4_ZB = CASE WHEN NVL(LN_TSE_HJ,0)=0 THEN NULL ELSE ROUND(100 * TSE_4_LJ / LN_TSE_HJ,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --6、汇总栏初始化
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B03107 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03107' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_TJBB_DT_B03108_HZ_NEW
prompt ============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03108_HZ_NEW
/*************************************************
 * 浙江出口企业分注册类型统计表（省、市局汇总）
 * 20210205，金额栏保留整数，比率保留小数点后1位
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LC_THISMONTH     VARCHAR2(6);--当月
  LC_THISYEAR      VARCHAR2(6);--当年1月
  LC_LASTMONTH     VARCHAR2(6);--上年同期
  LC_LASTYEAR      VARCHAR2(6);--上年1月
  
  LN_CKE_HJ        NUMBER(16,4);--出口额合计
  LN_TSE_HJ        NUMBER(16,4);--退税额合计
  LC_SQL_UPDATEHZ  VARCHAR2(4000);
  LD_SYSDATE       DATE;
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=SYSDATE;
  END IF;

  LC_THISMONTH   :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LC_THISYEAR    :=TO_CHAR(LD_SYSDATE,'YYYY')||'01';
  LC_LASTMONTH   :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYYMM');
  LC_LASTYEAR    :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYY')||'01';

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03108 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、计算并插入本年明细
  BEGIN
    INSERT INTO TJBB_DT_B03108 (SSNY,BBLC,SWJGDM,CKE,TMSE,CKE_LAST,TMSE_LAST)
      WITH FL_DJZCLX AS (SELECT NVL(B.DJZCLX_JS,'190') AS DJZCLX_JS, NVL(B.JSMODE,'2') AS JSMODE,  
                                SUM(CASE WHEN SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH THEN USD_AMT_ALL ELSE 0 END)/10000 AS USD_AMT, 
                                SUM(CASE WHEN SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH THEN TS_AMT_ALL  ELSE 0 END)/10000 AS TS_AMT, 
                                SUM(CASE WHEN SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH THEN USD_AMT_ALL ELSE 0 END)/10000 AS USD_AMT_LAST, 
                                SUM(CASE WHEN SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH THEN TS_AMT_ALL  ELSE 0 END)/10000 AS TS_AMT_LAST
                           FROM TL_TSSH.TJBB_FHXX_CPCODE A
                           LEFT JOIN TL_TSSH.GLXT_BB_SHXT_DJXX B ON A.XMFL=B.CPCODE
                          WHERE ((V_SWCODE='13300000000'  AND (A.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                                 (V_SWCODE<>'13300000000' AND (A.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
                            AND ((SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH) OR (SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH))
                          GROUP BY B.DJZCLX_JS, B.JSMODE)
    SELECT LC_THISMONTH, '01', V_SWCODE, ROUND(SUM(USD_AMT),0), ROUND(SUM(TS_AMT),0), ROUND(SUM(USD_AMT_LAST),0), ROUND(SUM(TS_AMT_LAST),0)
      FROM FL_DJZCLX T
     UNION ALL
    SELECT LC_THISMONTH, '02', V_SWCODE, ROUND(SUM(USD_AMT),0), ROUND(SUM(TS_AMT),0), ROUND(SUM(USD_AMT_LAST),0), ROUND(SUM(TS_AMT_LAST),0)
      FROM FL_DJZCLX T
     WHERE T.DJZCLX_JS IN ('110','141','143','151','161','162','164','165')
     UNION ALL
    SELECT LC_THISMONTH, '03', V_SWCODE, ROUND(SUM(USD_AMT),0), ROUND(SUM(TS_AMT),0), ROUND(SUM(USD_AMT_LAST),0), ROUND(SUM(TS_AMT_LAST),0)
      FROM FL_DJZCLX T
     WHERE SUBSTR(T.DJZCLX_JS,1,1) IN ('2','3')
     UNION ALL
    SELECT LC_THISMONTH, '04', V_SWCODE, ROUND(SUM(USD_AMT),0), ROUND(SUM(TS_AMT),0), ROUND(SUM(USD_AMT_LAST),0), ROUND(SUM(TS_AMT_LAST),0)
      FROM FL_DJZCLX T
     WHERE SUBSTR(T.DJZCLX_JS,1,1) NOT IN ('2','3')
       AND T.DJZCLX_JS NOT IN ('110','141','143','151','161','162','164','165')
     UNION ALL
    SELECT LC_THISMONTH, '05', V_SWCODE, ROUND(SUM(USD_AMT),0), ROUND(SUM(TS_AMT),0), ROUND(SUM(USD_AMT_LAST),0), ROUND(SUM(TS_AMT_LAST),0)
      FROM FL_DJZCLX T
     WHERE T.JSMODE<>'1'
     UNION ALL
    SELECT LC_THISMONTH, '06', V_SWCODE, ROUND(SUM(USD_AMT),0), ROUND(SUM(TS_AMT),0), ROUND(SUM(USD_AMT_LAST),0), ROUND(SUM(TS_AMT_LAST),0)
      FROM FL_DJZCLX T
     WHERE T.JSMODE<>'1' 
       AND T.DJZCLX_JS IN ('110','141','143','151','161','162','164','165')
     UNION ALL
    SELECT LC_THISMONTH, '07', V_SWCODE, ROUND(SUM(USD_AMT),0), ROUND(SUM(TS_AMT),0), ROUND(SUM(USD_AMT_LAST),0), ROUND(SUM(TS_AMT_LAST),0)
      FROM FL_DJZCLX T
     WHERE T.JSMODE<>'1' 
       AND SUBSTR(T.DJZCLX_JS,1,1) IN ('2','3')
     UNION ALL
    SELECT LC_THISMONTH, '08', V_SWCODE, ROUND(SUM(USD_AMT),0), ROUND(SUM(TS_AMT),0), ROUND(SUM(USD_AMT_LAST),0), ROUND(SUM(TS_AMT_LAST),0)
      FROM FL_DJZCLX T
     WHERE T.JSMODE<>'1' 
       AND SUBSTR(T.DJZCLX_JS,1,1) NOT IN ('2','3')
       AND T.DJZCLX_JS NOT IN ('110','141','143','151','161','162','164','165')
     UNION ALL
    SELECT LC_THISMONTH, '09', V_SWCODE, ROUND(SUM(USD_AMT),0), ROUND(SUM(TS_AMT),0), ROUND(SUM(USD_AMT_LAST),0), ROUND(SUM(TS_AMT_LAST),0)
      FROM FL_DJZCLX T
     WHERE T.JSMODE='1'
     UNION ALL
    SELECT LC_THISMONTH, '10', V_SWCODE, ROUND(SUM(USD_AMT),0), ROUND(SUM(TS_AMT),0), ROUND(SUM(USD_AMT_LAST),0), ROUND(SUM(TS_AMT_LAST),0)
      FROM FL_DJZCLX T
     WHERE T.JSMODE='1' 
       AND T.DJZCLX_JS IN ('110','141','143','151','161','162','164','165')
     UNION ALL
    SELECT LC_THISMONTH, '11', V_SWCODE, ROUND(SUM(USD_AMT),0), ROUND(SUM(TS_AMT),0), ROUND(SUM(USD_AMT_LAST),0), ROUND(SUM(TS_AMT_LAST),0)
      FROM FL_DJZCLX T
     WHERE T.JSMODE='1' 
       AND SUBSTR(T.DJZCLX_JS,1,1) IN ('2','3')
     UNION ALL
    SELECT LC_THISMONTH, '12', V_SWCODE, ROUND(SUM(USD_AMT),0), ROUND(SUM(TS_AMT),0), ROUND(SUM(USD_AMT_LAST),0), ROUND(SUM(TS_AMT_LAST),0)
      FROM FL_DJZCLX T
     WHERE T.JSMODE='1' 
       AND SUBSTR(T.DJZCLX_JS,1,1) NOT IN ('2','3')
       AND T.DJZCLX_JS NOT IN ('110','141','143','151','161','162','164','165')
    ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --2、计算并插入合计数
  BEGIN
    SELECT CKE, TMSE
      INTO LN_CKE_HJ, LN_TSE_HJ
      FROM TJBB_DT_B03108
     WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH AND BBLC='01';
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  --4、同比计算
  BEGIN
    UPDATE TJBB_DT_B03108
       SET CKE_TB  = CASE WHEN NVL(CKE_LAST,0)=0  THEN NULL ELSE ROUND(100 * CKE  / CKE_LAST  -100,1) END,
           TMSE_TB = CASE WHEN NVL(TMSE_LAST,0)=0 THEN NULL ELSE ROUND(100 * TMSE / TMSE_LAST -100,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --5、占比计算
  BEGIN
    UPDATE TJBB_DT_B03108 T
       SET CKE_ZB  = CASE WHEN NVL(LN_CKE_HJ,0)=0 THEN NULL ELSE ROUND(100 * CKE  / LN_CKE_HJ,1) END,
           TMSE_ZB = CASE WHEN NVL(LN_TSE_HJ,0)=0 THEN NULL ELSE ROUND(100 * TMSE / LN_TSE_HJ,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --6、汇总栏初始化
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B03108 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03108' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_TJBB_DT_B03109_HZ_NEW
prompt ============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03109_HZ_NEW
/*************************************************
 * 浙江省分出口海关分布情况统计表
 * 20210205，金额栏保留整数，比率保留小数点后1位
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LC_THISMONTH     VARCHAR2(6);--当月
  LC_THISYEAR      VARCHAR2(6);--当年1月
  LC_LASTMONTH     VARCHAR2(6);--上年同期
  LC_LASTYEAR      VARCHAR2(6);--上年1月
  
  LN_CKE_HJ        NUMBER(16,4);--出口额合计
  LN_TSE_HJ        NUMBER(16,4);--退税额合计
  LN_CKE_LAST      NUMBER(16,4);--出口额合计
  LN_TSE_LAST      NUMBER(16,4);--退税额合计
  LN_CKE_OTHER     NUMBER(16,4);--出口额合计
  LN_CKE_OTHER_LAST     NUMBER(16,4);--出口额合计
  
  V_TEMP           NUMBER(10, 0) := 0;
  LC_SQL_UPDATEHZ  VARCHAR2(4000);
  LD_SYSDATE       DATE;
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=SYSDATE;
  END IF;
  
  LC_THISMONTH   :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LC_THISYEAR    :=TO_CHAR(LD_SYSDATE,'YYYY')||'01';
  LC_LASTMONTH   :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYYMM');
  LC_LASTYEAR    :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYY')||'01';

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03109_MID WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    DELETE FROM TJBB_DT_B03109 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、中间表数据计算
  BEGIN
    INSERT INTO TJBB_DT_B03109_MID (SWJGDM,SSNY,GBDM,CKE_LJ,TSE_LJ,CKPM)
    SELECT V_SWCODE, LC_THISMONTH, XMFL, ROUND(SUM(USD_AMT)/10000,0), ROUND(SUM(TS_AMT)/10000,0), ROW_NUMBER() OVER (ORDER BY SUM(USD_AMT) DESC)
      FROM TL_TSSH.TJBB_FHXX_HGCODE
     WHERE ((V_SWCODE='13300000000'  AND (SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
            (V_SWCODE<>'13300000000' AND (SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
       AND SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH
     GROUP BY XMFL;
    COMMIT;
    
    SELECT COUNT(1)
      INTO V_TEMP
      FROM TJBB_DT_B03109_MID
     WHERE SWJGDM=V_SWCODE AND SSNY=LC_LASTMONTH;
    IF V_TEMP = 0 THEN
      BEGIN
        INSERT INTO TJBB_DT_B03109_MID (SWJGDM,SSNY,GBDM,CKE_LJ,TSE_LJ,CKPM)
        SELECT V_SWCODE, LC_LASTMONTH, XMFL, ROUND(SUM(USD_AMT)/10000,0), ROUND(SUM(TS_AMT)/10000,0), ROW_NUMBER() OVER (ORDER BY SUM(USD_AMT) DESC)
          FROM TL_TSSH.TJBB_FHXX_HGCODE
         WHERE ((V_SWCODE='13300000000'  AND (SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                (V_SWCODE<>'13300000000' AND (SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))))) 
           AND SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH
         GROUP BY XMFL;
        COMMIT;
      END;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --2、计算并插入本年前20名明细及上年同期
  BEGIN
    INSERT INTO TJBB_DT_B03109 (SSNY,BBLC,SWJGDM,GBDM,HGMC,CKE_LJ,CKE_LJ_LAST)
    SELECT A.SSNY, CASE WHEN A.CKPM<9 THEN '0' ELSE '' END || (A.CKPM + 1), A.SWJGDM, A.GBDM, B.HGMC, A.CKE_LJ, C.CKE_LJ
      FROM TJBB_DT_B03109_MID A
     INNER JOIN DM_HGCODE B ON B.HGCODE=A.GBDM
      LEFT JOIN TJBB_DT_B03109_MID C ON C.SWJGDM=A.SWJGDM AND C.SSNY=LC_LASTMONTH AND C.GBDM=A.GBDM
     WHERE A.SWJGDM=V_SWCODE
       AND A.SSNY=LC_THISMONTH
       AND A.CKPM<=20;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --3、计算并插入合计数、其他数
  BEGIN
    SELECT ROUND(SUM(USD_AMT)/10000,0), ROUND(SUM(TS_AMT)/10000,0)
      INTO LN_CKE_HJ, LN_TSE_HJ
      FROM TL_TSSH.TJBB_FHXX_HGCODE
     WHERE ((V_SWCODE='13300000000'  AND (SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
            (V_SWCODE<>'13300000000' AND (SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
       AND SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH;

    SELECT ROUND(SUM(USD_AMT)/10000,0), ROUND(SUM(TS_AMT)/10000,0)
      INTO LN_CKE_LAST, LN_TSE_LAST
      FROM TL_TSSH.TJBB_FHXX_HGCODE
     WHERE ((V_SWCODE='13300000000'  AND (SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
            (V_SWCODE<>'13300000000' AND (SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
       AND SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH;

    SELECT LN_CKE_HJ - SUM(CKE_LJ), LN_CKE_LAST - SUM(CKE_LJ_LAST)
      INTO LN_CKE_OTHER, LN_CKE_OTHER_LAST
      FROM TJBB_DT_B03109
     WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    
    INSERT INTO TJBB_DT_B03109 (SSNY,BBLC,SWJGDM,GBDM,HGMC,CKE_LJ,CKE_LJ_LAST)
    SELECT LC_THISMONTH, '01', V_SWCODE, '', '合计', LN_CKE_HJ, LN_CKE_LAST
      FROM DUAL;
    COMMIT;
    
    INSERT INTO TJBB_DT_B03109 (SSNY,BBLC,SWJGDM,GBDM,HGMC,CKE_LJ,CKE_LJ_LAST)
    SELECT LC_THISMONTH, '22', V_SWCODE, '', '其他', LN_CKE_OTHER, LN_CKE_OTHER_LAST
      FROM DUAL;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  --4、同比计算
  BEGIN
    UPDATE TJBB_DT_B03109
       SET CKE_TB = CASE WHEN NVL(CKE_LJ_LAST,0)=0 THEN NULL ELSE ROUND(100 * CKE_LJ / CKE_LJ_LAST -100,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --5、占比计算
  BEGIN
    UPDATE TJBB_DT_B03109 T
       SET CKE_ZB = CASE WHEN NVL(LN_CKE_HJ,0)=0 THEN NULL ELSE ROUND(100 * CKE_LJ / LN_CKE_HJ,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --6、汇总栏初始化
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B03109 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03109' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

