prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03110_HZ_NEW
/*************************************************
 * 浙江省分出口市场统计表
 * 20210205，金额栏保留整数，比率保留小数点后1位
 * 20210630，应省局吴嘉需求，全部国家排名
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LC_THISMONTH     VARCHAR2(6);--当月
  LC_THISYEAR      VARCHAR2(6);--当年1月
  LC_LASTMONTH     VARCHAR2(6);--上年同期
  LC_LASTYEAR      VARCHAR2(6);--上年1月
  
  LN_CKE_HJ        NUMBER(16,4);--出口额合计
  LN_TSE_HJ        NUMBER(16,4);--退税额合计
  LN_CKE_HJ_LAST   NUMBER(16,4);--出口额合计
  LN_TSE_HJ_LAST   NUMBER(16,4);--退税额合计
  LN_CKE_OTHER     NUMBER(16,4);--出口额合计
  LN_TSE_OTHER     NUMBER(16,4);--退税额合计
  LN_CKE_OTHER_LAST     NUMBER(16,4);--出口额合计
  LN_TSE_OTHER_LAST     NUMBER(16,4);--退税额合计

  LC_SQL_UPDATEHZ  VARCHAR2(4000);
  LD_SYSDATE       DATE;
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=SYSDATE;
  END IF;
  
  LC_THISMONTH   :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LC_THISYEAR    :=TO_CHAR(LD_SYSDATE,'YYYY')||'01';
  LC_LASTMONTH   :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYYMM');
  LC_LASTYEAR    :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYY')||'01';

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03110_MID WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    DELETE FROM TJBB_DT_B03110_MID WHERE SWJGDM=V_SWCODE AND SSNY=LC_LASTMONTH;
    DELETE FROM TJBB_DT_B03110 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、中间表数据计算
  BEGIN
    INSERT INTO TJBB_DT_B03110_MID (SWJGDM,SSNY,DMTYPE,GBDM,CKE_LJ,TSE_LJ,CKPM)
    SELECT V_SWCODE, LC_THISMONTH, 'DQ', DQ_CODE, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
      FROM (SELECT A.DQ_CODE, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM DM_DQCODE A
             INNER JOIN DM_DQGROUP B ON A.DQ_CODE=B.DQ_CODE
              LEFT JOIN TL_TSSH.TJBB_FHXX_GBCODE C ON B.GB_CODE=C.XMFL AND 
                        ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                         (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))))) AND C.SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH
             WHERE A.DQ_TYPE='DQ'
             GROUP BY A.DQ_CODE)
     UNION ALL
    SELECT V_SWCODE, LC_THISMONTH, 'ZZ', DQ_CODE, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
      FROM (SELECT A.DQ_CODE, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM DM_DQCODE A
             INNER JOIN DM_DQGROUP B ON A.DQ_CODE=B.DQ_CODE
              LEFT JOIN TL_TSSH.TJBB_FHXX_GBCODE C ON B.GB_CODE=C.XMFL AND 
                        ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                         (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))))) AND C.SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH
             WHERE A.DQ_TYPE='ZZ'
             GROUP BY A.DQ_CODE)
     UNION ALL
    SELECT V_SWCODE, LC_THISMONTH, 'GJ', XMFL, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
      FROM (SELECT XMFL, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM TL_TSSH.TJBB_FHXX_GBCODE C
             WHERE ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                    (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
               AND SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH AND XMFL<>'142'
             GROUP BY XMFL)
     UNION ALL
    SELECT V_SWCODE, LC_THISMONTH, 'GJ', XMFL, USD_AMT, TSE_AMT, 999
      FROM (SELECT '142' AS XMFL, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM TL_TSSH.TJBB_FHXX_GBCODE C
             WHERE ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                    (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
               AND SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH AND XMFL='142');
    COMMIT;
    
    INSERT INTO TJBB_DT_B03110_MID (SWJGDM,SSNY,DMTYPE,GBDM,CKE_LJ,TSE_LJ,CKPM)
    SELECT V_SWCODE, LC_LASTMONTH, 'DQ', DQ_CODE, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
      FROM (SELECT A.DQ_CODE, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM DM_DQCODE A
             INNER JOIN DM_DQGROUP B ON A.DQ_CODE=B.DQ_CODE
              LEFT JOIN TL_TSSH.TJBB_FHXX_GBCODE C ON B.GB_CODE=C.XMFL AND 
                        ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                         (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))))) AND C.SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH
             WHERE A.DQ_TYPE='DQ'
             GROUP BY A.DQ_CODE)
     UNION ALL
    SELECT V_SWCODE, LC_LASTMONTH, 'ZZ', DQ_CODE, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
      FROM (SELECT A.DQ_CODE, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM DM_DQCODE A
             INNER JOIN DM_DQGROUP B ON A.DQ_CODE=B.DQ_CODE
              LEFT JOIN TL_TSSH.TJBB_FHXX_GBCODE C ON B.GB_CODE=C.XMFL AND 
                        ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                         (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))))) AND C.SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH
             WHERE A.DQ_TYPE='ZZ'
             GROUP BY A.DQ_CODE)
     UNION ALL
    SELECT V_SWCODE, LC_LASTMONTH, 'GJ', XMFL, USD_AMT, TSE_AMT, ROW_NUMBER() OVER (ORDER BY USD_AMT DESC)
      FROM (SELECT XMFL, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM TL_TSSH.TJBB_FHXX_GBCODE C
             WHERE ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                    (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))))) AND SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH AND XMFL<>'142'
             GROUP BY XMFL)
     UNION ALL
    SELECT V_SWCODE, LC_LASTMONTH, 'GJ', XMFL, USD_AMT, TSE_AMT, 999
      FROM (SELECT '142' AS XMFL, ROUND(SUM(C.USD_AMT)/10000,0) AS USD_AMT, ROUND(SUM(C.TS_AMT)/10000,0) AS TSE_AMT
              FROM TL_TSSH.TJBB_FHXX_GBCODE C
             WHERE ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                    (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))))) AND SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH AND XMFL='142');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --2、计算并插入本年明细及上年同期
  BEGIN
    INSERT INTO TJBB_DT_B03110 (SSNY,BBLC,SWJGDM,ITEM,CKE_USD,TMSE,CKE_USD_LAST,TMSE_LAST)
    SELECT LC_THISMONTH, '1000', V_SWCODE, '国别地区', NULL, NULL, NULL, NULL
      FROM DUAL
     UNION ALL
    SELECT B.SSNY, CASE WHEN B.CKPM<10 THEN '100' ELSE '10' END || B.CKPM, B.SWJGDM, A.DQ_NAME, B.CKE_LJ, B.TSE_LJ, C.CKE_LJ, C.TSE_LJ
      FROM DM_DQCODE A
     INNER JOIN TJBB_DT_B03110_MID B ON A.DQ_CODE=B.GBDM AND B.SWJGDM=V_SWCODE AND B.SSNY=LC_THISMONTH AND B.DMTYPE='DQ'
      LEFT JOIN TJBB_DT_B03110_MID C ON A.DQ_CODE=C.GBDM AND C.SWJGDM=V_SWCODE AND C.SSNY=LC_LASTMONTH AND C.DMTYPE='DQ'
     WHERE A.DQ_TYPE='DQ'
     UNION ALL
    SELECT LC_THISMONTH, '2000', V_SWCODE, '区域（经济）组织', NULL, NULL, NULL, NULL
      FROM DUAL
     UNION ALL
    SELECT B.SSNY, CASE WHEN B.CKPM<10 THEN '200' ELSE '20' END || B.CKPM, B.SWJGDM, A.DQ_NAME, B.CKE_LJ, B.TSE_LJ, C.CKE_LJ, C.TSE_LJ
      FROM DM_DQCODE A
     INNER JOIN TJBB_DT_B03110_MID B ON A.DQ_CODE=B.GBDM AND B.SWJGDM=V_SWCODE AND B.SSNY=LC_THISMONTH AND B.DMTYPE='ZZ'
      LEFT JOIN TJBB_DT_B03110_MID C ON A.DQ_CODE=C.GBDM AND C.SWJGDM=V_SWCODE AND C.SSNY=LC_LASTMONTH AND C.DMTYPE='ZZ'
     WHERE A.DQ_TYPE='ZZ'
     UNION ALL
    SELECT B.SSNY, CASE WHEN B.CKPM<10 THEN '300' WHEN B.CKPM<100 THEN '30' ELSE '3' END || B.CKPM, B.SWJGDM, A.GB_NAME, B.CKE_LJ, B.TSE_LJ, C.CKE_LJ, C.TSE_LJ
      FROM DM_GBCODE A
     INNER JOIN TJBB_DT_B03110_MID B ON A.GB_CODE=B.GBDM AND B.SWJGDM=V_SWCODE AND B.SSNY=LC_THISMONTH AND B.DMTYPE='GJ'
      LEFT JOIN TJBB_DT_B03110_MID C ON A.GB_CODE=C.GBDM AND C.SWJGDM=V_SWCODE AND C.SSNY=LC_LASTMONTH AND C.DMTYPE='GJ';
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --3、计算并插入合计数及其他数
  BEGIN
    SELECT ROUND(SUM(C.USD_AMT)/10000,0), ROUND(SUM(C.TS_AMT)/10000,0)
      INTO LN_CKE_HJ, LN_TSE_HJ
      FROM TL_TSSH.TJBB_FHXX_GBCODE C
     WHERE ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
            (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
        AND C.SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH;

    SELECT ROUND(SUM(C.USD_AMT)/10000,0), ROUND(SUM(C.TS_AMT)/10000,0)
      INTO LN_CKE_HJ_LAST, LN_TSE_HJ_LAST
      FROM TL_TSSH.TJBB_FHXX_GBCODE C
     WHERE ((V_SWCODE='13300000000'  AND (C.SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
            (V_SWCODE<>'13300000000' AND (C.SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))))) 
       AND C.SSNY BETWEEN  LC_LASTYEAR AND LC_LASTMONTH;

    SELECT LN_CKE_HJ - SUM(CKE_USD),LN_TSE_HJ - SUM(TMSE),LN_CKE_HJ_LAST - SUM(CKE_USD_LAST),LN_TSE_HJ_LAST - SUM(TMSE_LAST)
      INTO LN_CKE_OTHER, LN_TSE_OTHER, LN_CKE_OTHER_LAST, LN_TSE_OTHER_LAST
      FROM TJBB_DT_B03110
     WHERE SSNY=LC_THISMONTH AND BBLC LIKE '3%' AND SWJGDM=V_SWCODE;
    
    INSERT INTO TJBB_DT_B03110 (SSNY,BBLC,SWJGDM,ITEM,CKE_USD,TMSE,CKE_USD_LAST,TMSE_LAST)
    SELECT LC_THISMONTH, '3000', V_SWCODE, '所有国家合计', LN_CKE_HJ, LN_TSE_HJ, LN_CKE_HJ_LAST, LN_TSE_HJ_LAST
      FROM DUAL;
    INSERT INTO TJBB_DT_B03110 (SSNY,BBLC,SWJGDM,ITEM,CKE_USD,TMSE,CKE_USD_LAST,TMSE_LAST)
    SELECT LC_THISMONTH, '4000', V_SWCODE, '其他', LN_CKE_OTHER, LN_TSE_OTHER, LN_CKE_OTHER_LAST, LN_TSE_OTHER_LAST
      FROM DUAL;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  --5、同比计算
  BEGIN
    UPDATE TJBB_DT_B03110
       SET CKE_TB  = CASE WHEN NVL(CKE_USD_LAST,0)=0 THEN NULL ELSE ROUND(100 * CKE_USD / CKE_USD_LAST -100,1) END,
           TMSE_TB = CASE WHEN NVL(TMSE_LAST,0)=0    THEN NULL ELSE ROUND(100 * TMSE    / TMSE_LAST    -100,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --6、占比计算
  BEGIN
    UPDATE TJBB_DT_B03110 T
       SET CKE_ZB  = CASE WHEN NVL(LN_CKE_HJ,0)=0 THEN NULL ELSE ROUND(100 * CKE_USD / LN_CKE_HJ,1) END,
           TMSE_ZB = CASE WHEN NVL(LN_TSE_HJ,0)=0 THEN NULL ELSE ROUND(100 * TMSE / LN_TSE_HJ,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --7、汇总栏初始化
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B03110 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03110' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_TJBB_DT_B03112_HZ_NEW
prompt ============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03112_HZ_NEW
/*************************************************
 * 浙江省对美出口商品分布情况统计表（省、市局汇总）
 * 与03104的区别，退税额改为退免税额，出口国限定为美国
 * 20210205，金额栏保留整数，比率保留小数点后1位
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LC_THISMONTH     VARCHAR2(6);--当月
  LC_THISYEAR      VARCHAR2(6);--当年1月
  LC_LASTMONTH     VARCHAR2(6);--上年同期
  LC_LASTYEAR      VARCHAR2(6);--上年1月
  
  LN_CKE_THIS      NUMBER(16,4);--本年出口额合计
  LN_TSE_THIS      NUMBER(16,4);--本年退税额合计
  LN_CKE_LAST      NUMBER(16,4);--上年出口额合计
  LN_TSE_LAST      NUMBER(16,4);--上年退税额合计
  LC_SQL_UPDATEHZ  VARCHAR2(4000);
  LD_SYSDATE       DATE;
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=SYSDATE;
  END IF;

  LC_THISMONTH   :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LC_THISYEAR    :=TO_CHAR(LD_SYSDATE,'YYYY')||'01';
  LC_LASTMONTH   :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYYMM');
  LC_LASTYEAR    :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYY')||'01';

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03112 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、计算并插入本年明细
  BEGIN
    INSERT INTO TJBB_DT_B03112 (SSNY,BBLC,SWJGDM,SPDLDM,SPDL,SPMC,CKE_YEAR,TSE_YEAR,CKE_YEAR_LAST,TSE_YEAR_LAST)
      WITH THISYEAR AS (SELECT XMFL, SUM(USD_AMT_USA) AS USD_AMT, SUM(TS_AMT_USA) AS TS_AMT
                          FROM TL_TSSH.TJBB_FHXX_CMCODE
                         WHERE ((V_SWCODE='13300000000'  AND (SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                                (V_SWCODE<>'13300000000' AND (SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
                           AND SSNY BETWEEN LC_THISYEAR AND LC_THISMONTH
                         GROUP BY XMFL),
           LASTYEAR AS (SELECT XMFL, SUM(USD_AMT_USA) AS USD_AMT, SUM(TS_AMT_USA) AS TS_AMT
                          FROM TL_TSSH.TJBB_FHXX_CMCODE
                         WHERE ((V_SWCODE='13300000000'  AND (SWCODE IN (SELECT SWJG_DM FROM TL_ADMIN.DM_SWJG WHERE TSJG_BZ='1'))) OR 
                                (V_SWCODE<>'13300000000' AND (SWCODE IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE))))))
                           AND SSNY BETWEEN LC_LASTYEAR AND LC_LASTMONTH
                         GROUP BY XMFL)
    SELECT LC_THISMONTH, 1+ ROW_NUMBER() OVER (ORDER BY SUM(NVL(C.USD_AMT,0)) DESC,SUM(NVL(D.USD_AMT,0)) DESC) AS BBLC, V_SWCODE, 
           A.SPML, A.MLDM, A.MLMC, 
           ROUND(SUM(C.USD_AMT)/10000,0), ROUND(SUM(C.TS_AMT)/10000,0), ROUND(SUM(D.USD_AMT)/10000,0), ROUND(SUM(D.TS_AMT)/10000,0)
      FROM DM_SPML A
     INNER JOIN DM_SPFL B ON A.SPML=B.SPML
      LEFT JOIN THISYEAR C ON C.XMFL = B.SPDL
      LEFT JOIN LASTYEAR D ON D.XMFL = B.SPDL
      GROUP BY A.SPML, A.MLDM, A.MLMC;
    COMMIT;
    
    UPDATE TJBB_DT_B03112
       SET BBLC = '0'||BBLC
     WHERE LENGTH(BBLC)<2;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --2、计算并插入合计数
  BEGIN
    SELECT SUM(CKE_YEAR), SUM(TSE_YEAR), SUM(CKE_YEAR_LAST), SUM(TSE_YEAR_LAST)
      INTO LN_CKE_THIS, LN_TSE_THIS, LN_CKE_LAST, LN_TSE_LAST
      FROM TJBB_DT_B03112
     WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;

    INSERT INTO TJBB_DT_B03112 (SSNY,BBLC,SWJGDM,SPDLDM,SPDL,SPMC,CKE_YEAR,TSE_YEAR, CKE_YEAR_LAST, TSE_YEAR_LAST)
    SELECT LC_THISMONTH, '01', V_SWCODE,
           'HJ', '', '合计',
           LN_CKE_THIS, LN_TSE_THIS, LN_CKE_LAST, LN_TSE_LAST
      FROM DUAL;
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  --4、同比计算
  BEGIN
    UPDATE TJBB_DT_B03112
       SET CKE_TB = CASE WHEN NVL(CKE_YEAR_LAST,0)=0 THEN NULL ELSE ROUND(100 * CKE_YEAR / CKE_YEAR_LAST -100,1) END,
           TSE_TB = CASE WHEN NVL(TSE_YEAR_LAST,0)=0 THEN NULL ELSE ROUND(100 * TSE_YEAR / TSE_YEAR_LAST -100,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --5、占比计算
  BEGIN
    UPDATE TJBB_DT_B03112 T
       SET CKE_ZB = CASE WHEN NVL(LN_CKE_THIS,0)=0 THEN NULL ELSE ROUND(100 * CKE_YEAR / LN_CKE_THIS,1) END,
           TSE_ZB = CASE WHEN NVL(LN_TSE_THIS,0)=0 THEN NULL ELSE ROUND(100 * TSE_YEAR / LN_TSE_THIS,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --6、汇总栏初始化
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B03112 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03112' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_TJBB_DT_B03113_HZ_NEW
prompt ============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03113_HZ_NEW
/*************************************************
 * 浙江省对美主要出口企业情况表（省、市局汇总）
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LC_THISMONTH     VARCHAR2(6);--当月
  LC_THISYEAR      VARCHAR2(6);--当年首月
  LC_LASTMONTH     VARCHAR2(6);--上年同期
  LC_LASTYEAR      VARCHAR2(6);--上年首月
  LC_SQL_UPDATEHZ  VARCHAR2(4000);
  LD_SYSDATE       DATE;
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=SYSDATE;
  END IF;

  LC_THISMONTH   :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LC_THISYEAR    :=TO_CHAR(LD_SYSDATE,'YYYY')||'01';
  LC_LASTMONTH   :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYYMM');
  LC_LASTYEAR    :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYY')||'01';

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03113 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、本年前50名当年数据
  BEGIN
    INSERT INTO TJBB_DT_B03113 
                (SSNY,BBLC,SWJGDM,CPCODE,QYHGDM,QYMC,JSMODE,JSMODEMC,PM,
                USA_CKE_YEAR,CKE_YEAR,USA_TMSE_YEAR,TMSE_YEAR,
                USA_CKE_YEAR_LAST,CKE_YEAR_LAST,USA_TMSE_YEAR_LAST,TMSE_YEAR_LAST,
                USA_CKE_TB,CKE_TB,USA_TMSE_TB,TMSE_TB,
                CKE_YEAR_ZB,CKE_YEAR_ZB_LAST,TMSE_YEAR_ZB,TMSE_YEAR_ZB_LAST)
    SELECT LC_THISMONTH,JSMODE||CASE WHEN PM<10 THEN '0' ELSE '' END||PM,V_SWCODE,CPCODE,QYHGDM,QYMC,JSMODE,JSMODEMC,PM,
           USA_CKE_YEAR,CKE_YEAR,USA_TMSE_YEAR,TMSE_YEAR,
           USA_CKE_YEAR_LAST,CKE_YEAR_LAST,USA_TMSE_YEAR_LAST,TMSE_YEAR_LAST,
           USA_CKE_TB,CKE_TB,USA_TMSE_TB,TMSE_TB,
           CKE_YEAR_ZB,CKE_YEAR_ZB_LAST,TMSE_YEAR_ZB,TMSE_YEAR_ZB_LAST
      FROM (SELECT CPCODE,QYHGDM,QYMC,JSMODE,JSMODEMC,
                   USA_CKE_YEAR,CKE_YEAR,USA_TMSE_YEAR,TMSE_YEAR,
                   USA_CKE_YEAR_LAST,CKE_YEAR_LAST,USA_TMSE_YEAR_LAST,TMSE_YEAR_LAST,
                   USA_CKE_TB,CKE_TB,USA_TMSE_TB,TMSE_TB,
                   CKE_YEAR_ZB,CKE_YEAR_ZB_LAST,TMSE_YEAR_ZB,TMSE_YEAR_ZB_LAST,
                   ROW_NUMBER() OVER (PARTITION BY JSMODE ORDER BY USA_CKE_YEAR DESC) AS PM
              FROM TJBB_DT_B03113 B 
             WHERE B.SWJGDM IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))
               AND B.SSNY=LC_THISMONTH)
     WHERE PM<=50;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --2、汇总栏初始化
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B03113 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03113' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_TJBB_DT_B03114_HZ_NEW
prompt ============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03114_HZ_NEW
/*************************************************
 * 对“一带一路”国家出口退（免）税情况统计表（省、市局汇总）
 * 表结构与浙江省分出口市场统计表一样，算法条件有变化
 * 20210205，金额栏保留整数，比率保留小数点后1位
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LC_THISMONTH     VARCHAR2(6);--当月
  LC_THISYEAR      VARCHAR2(6);--当年首月
  LC_LASTMONTH     VARCHAR2(6);--上年同期
  LN_CKE_HJ        NUMBER(16,4);--出口额合计
  LN_TSE_HJ        NUMBER(16,4);--退税额合计
  LN_CKE_HJ_LAST   NUMBER(16,4);--出口额合计
  LN_TSE_HJ_LAST   NUMBER(16,4);--退税额合计

  V_TEMP           NUMBER(10, 0) := 0;
  LC_SQL_UPDATEHZ  VARCHAR2(4000);
  LD_SYSDATE       DATE;
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=SYSDATE;
  END IF;

  LC_THISMONTH   :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LC_THISYEAR    :=TO_CHAR(LD_SYSDATE,'YYYY')||'01';
  LC_LASTMONTH   :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYYMM');

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03114_MID WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    DELETE FROM TJBB_DT_B03114 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、中间表数据计算
  BEGIN
    INSERT INTO TJBB_DT_B03114_MID (SWJGDM,SSNY,DMTYPE,GBDM,CKE_LJ,TSE_LJ,CKPM)
    SELECT V_SWCODE, LC_THISMONTH, B.DMTYPE, B.GBDM, SUM(B.CKE_LJ), SUM(B.TSE_LJ), ROW_NUMBER() OVER (PARTITION BY B.DMTYPE ORDER BY SUM(NVL(B.CKE_LJ,0)) DESC)
      FROM TJBB_DT_B03114_MID B 
     WHERE B.SWJGDM IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))
       AND B.SSNY=LC_THISMONTH
     GROUP BY B.DMTYPE, B.GBDM;
    COMMIT;

    SELECT COUNT(1)
      INTO V_TEMP
      FROM TJBB_DT_B03114_MID
     WHERE SWJGDM=V_SWCODE AND SSNY=LC_LASTMONTH AND DMTYPE='GJ';
    IF V_TEMP = 0 THEN
      BEGIN
        DELETE FROM TJBB_DT_B03114_MID WHERE SWJGDM=V_SWCODE AND SSNY=LC_LASTMONTH;
        COMMIT;

        INSERT INTO TJBB_DT_B03114_MID (SWJGDM,SSNY,DMTYPE,GBDM,CKE_LJ,TSE_LJ,CKPM)
        SELECT V_SWCODE, LC_LASTMONTH, B.DMTYPE, B.GBDM, SUM(B.CKE_LJ), SUM(B.TSE_LJ), ROW_NUMBER() OVER (PARTITION BY B.DMTYPE ORDER BY SUM(NVL(B.CKE_LJ,0)) DESC)
          FROM TJBB_DT_B03114_MID B 
         WHERE B.SWJGDM IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))
           AND B.SSNY=LC_LASTMONTH
         GROUP BY B.DMTYPE, B.GBDM;
        COMMIT;
      END;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --2、计算并插入区域情况及本年前10名明细及上年同期
  BEGIN
    INSERT INTO TJBB_DT_B03114 (SSNY,BBLC,SWJGDM,ITEM,CKE_USD,TMSE,CKE_USD_LAST,TMSE_LAST)
    SELECT LC_THISMONTH, '100', V_SWCODE, '区域情况', NULL, NULL, NULL, NULL
      FROM DUAL
     UNION ALL
    SELECT B.SSNY, CASE WHEN B.CKPM<10 THEN '10' ELSE '1' END || B.CKPM, B.SWJGDM, A.DQ_NAME, B.CKE_LJ, B.TSE_LJ, C.CKE_LJ, C.TSE_LJ
      FROM DM_DQCODE A
     INNER JOIN TJBB_DT_B03114_MID B ON A.DQ_CODE=B.GBDM AND B.SWJGDM=V_SWCODE AND B.SSNY=LC_THISMONTH AND B.DMTYPE='BR'
      LEFT JOIN TJBB_DT_B03114_MID C ON A.DQ_CODE=C.GBDM AND C.SWJGDM=V_SWCODE AND C.SSNY=LC_LASTMONTH AND C.DMTYPE='BR'
     WHERE A.DQ_TYPE='BR'
     UNION ALL
    SELECT LC_THISMONTH, '200', V_SWCODE, '10个主要国别情况', NULL, NULL, NULL, NULL
      FROM DUAL
     UNION ALL
    SELECT B.SSNY, CASE WHEN B.CKPM<10 THEN '20' ELSE '2' END || B.CKPM, B.SWJGDM, A.GB_NAME, B.CKE_LJ, B.TSE_LJ, C.CKE_LJ, C.TSE_LJ
      FROM DM_GBCODE A
     INNER JOIN TJBB_DT_B03114_MID B ON A.GB_CODE=B.GBDM AND B.SWJGDM=V_SWCODE AND B.SSNY=LC_THISMONTH AND B.DMTYPE='GJ'
      LEFT JOIN TJBB_DT_B03114_MID C ON A.GB_CODE=C.GBDM AND C.SWJGDM=V_SWCODE AND C.SSNY=LC_LASTMONTH AND C.DMTYPE='GJ'
     WHERE B.CKPM<=10;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --3、计算并插入合计数
  BEGIN
    SELECT SUM(CKE_LJ), SUM(TSE_LJ)
      INTO LN_CKE_HJ, LN_TSE_HJ
      FROM TJBB_DT_B03114_MID
     WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH AND DMTYPE='GJ';

    SELECT SUM(CKE_LJ), SUM(TSE_LJ)
      INTO LN_CKE_HJ_LAST, LN_TSE_HJ_LAST
      FROM TJBB_DT_B03114_MID
     WHERE SWJGDM=V_SWCODE AND SSNY=LC_LASTMONTH AND DMTYPE='GJ';

    INSERT INTO TJBB_DT_B03114 (SSNY,BBLC,SWJGDM,ITEM,CKE_USD,TMSE,CKE_USD_LAST,TMSE_LAST)
    SELECT LC_THISMONTH, '001', V_SWCODE, '“一带一路”沿线64国', LN_CKE_HJ, LN_TSE_HJ, LN_CKE_HJ_LAST, LN_TSE_HJ_LAST
      FROM DUAL;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  --4、同比计算
  BEGIN
    UPDATE TJBB_DT_B03114
       SET CKE_TB  = CASE WHEN NVL(CKE_USD_LAST,0)=0 THEN NULL ELSE ROUND(100 * CKE_USD / CKE_USD_LAST -100,1) END,
           TMSE_TB = CASE WHEN NVL(TMSE_LAST,0)=0    THEN NULL ELSE ROUND(100 * TMSE    / TMSE_LAST    -100,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --5、占比计算
  BEGIN
    UPDATE TJBB_DT_B03114 T
       SET CKE_ZB  = CASE WHEN NVL(LN_CKE_HJ,0)=0 THEN NULL ELSE ROUND(100 * CKE_USD / LN_CKE_HJ,1) END,
           TMSE_ZB = CASE WHEN NVL(LN_TSE_HJ,0)=0 THEN NULL ELSE ROUND(100 * TMSE / LN_TSE_HJ,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  --6、汇总栏初始化
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B03114 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03114' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

prompt
prompt Creating procedure PRO_TJBB_DT_B03115_HZ_NEW
prompt ============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B03115_HZ_NEW
/*************************************************
 * 浙江省办理出口退税排名统计表（省、市局汇总）
 * 20210205，金额栏保留整数，比率保留小数点后1位
 ************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LC_THISMONTH     VARCHAR2(6);--当月
  LC_LASTMONTH     VARCHAR2(6);--上年同期

  LN_TMSE_HJ            NUMBER(16,4);--退（免）税额合计
  LN_TSE_HJ             NUMBER(16,4);--退税额合计
  LN_MDE_HJ             NUMBER(16,4);--免抵额合计
  LN_TMSE_HJ_LAST       NUMBER(16,4);--退（免）税额合计
  LN_TSE_HJ_LAST        NUMBER(16,4);--退税额合计
  LN_MDE_HJ_LAST        NUMBER(16,4);--免抵额合计
  LN_TMSE_OTHER         NUMBER(16,4);--退（免）税额合计
  LN_TSE_OTHER          NUMBER(16,4);--退税额合计
  LN_MDE_OTHER          NUMBER(16,4);--免抵额合计
  LN_TMSE_OTHER_LAST    NUMBER(16,4);--退（免）税额合计
  LN_TSE_OTHER_LAST     NUMBER(16,4);--退税额合计
  LN_MDE_OTHER_LAST     NUMBER(16,4);--免抵额合计

  LC_SQL_UPDATEHZ  VARCHAR2(4000);
  LD_SYSDATE       DATE;
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=SYSDATE;
  END IF;

  LC_THISMONTH   :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LC_LASTMONTH   :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYYMM');

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B03115 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、中间表数据计算
  BEGIN
    IF V_SWCODE='13300000000' THEN
      FOR CUR_PM IN (SELECT SWJGDM, JSMODE, DJXH, ROW_NUMBER() OVER (PARTITION BY JSMODE ORDER BY TMSE DESC) AS PM
                       FROM TJBB_DT_B03115_MID  
                      WHERE SSNY=LC_THISMONTH 
                        AND JSMODE IS NOT NULL)
      LOOP
        UPDATE TJBB_DT_B03115_MID T
           SET T.CKPM_3 = CUR_PM.PM
         WHERE T.SSNY=LC_THISMONTH AND T.JSMODE=CUR_PM.JSMODE AND T.SWJGDM=CUR_PM.SWJGDM AND T.DJXH=CUR_PM.DJXH;
        COMMIT;
      END LOOP;
    ELSE
      FOR CUR_PM IN (SELECT SWJGDM, JSMODE, DJXH, ROW_NUMBER() OVER (PARTITION BY JSMODE ORDER BY TMSE DESC) AS PM
                       FROM TJBB_DT_B03115_MID  
                      WHERE SWJGDM IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))
                        AND SSNY=LC_THISMONTH 
                        AND JSMODE IS NOT NULL)
      LOOP
        UPDATE TJBB_DT_B03115_MID T
           SET T.CKPM_2 = CUR_PM.PM
         WHERE T.SSNY=LC_THISMONTH AND T.JSMODE=CUR_PM.JSMODE AND T.SWJGDM=CUR_PM.SWJGDM AND T.DJXH=CUR_PM.DJXH;
        COMMIT;
      END LOOP;
    END IF;
  END;
  
  --2、查询并插入外贸（生产）各前10名
  BEGIN
    INSERT INTO TJBB_DT_B03115 (SSNY,BBLC,SWJGDM,DJXH,SHXYNO,QYMC,JSMODE,JSMODEMC,SWJG,TMSE,TSE,MDE,TMSE_LAST,TSE_LAST,MDE_LAST,TMSE_TB,XH)
    SELECT LC_THISMONTH, JSMODE||SUBSTR('00'||PM,-2), V_SWCODE,
           DJXH,SHXYNO,QYMC,JSMODE,JSMODEMC,SWJG,TMSE,TSE,MDE,TMSE_LAST,TSE_LAST,MDE_LAST,TMSE_TB,PM
      FROM (SELECT DJXH, SHXYNO, QYMC, JSMODE, JSMODEMC, SWJG, TMSE,TSE,MDE,TMSE_LAST,TSE_LAST,MDE_LAST,TMSE_TB,
                   ROW_NUMBER() OVER (PARTITION BY JSMODE ORDER BY TMSE DESC) AS PM
              FROM TJBB_DT_B03115 B 
             WHERE B.SWJGDM IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))
               AND B.SSNY=LC_THISMONTH 
               AND B.JSMODE IS NOT NULL)
     WHERE PM<=20;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --3、计算并插入合计数、小计数与其他数
  BEGIN
    SELECT SUM(TMSE),SUM(TSE),SUM(MDE),SUM(TMSE_LAST),SUM(TSE_LAST),SUM(MDE_LAST)
      INTO LN_TMSE_HJ, LN_TSE_HJ, LN_MDE_HJ, LN_TMSE_HJ_LAST, LN_TSE_HJ_LAST, LN_MDE_HJ_LAST
      FROM TJBB_DT_B03115 A
     WHERE A.SWJGDM IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))
       AND A.SSNY=LC_THISMONTH
       AND A.BBLC='000';
    INSERT INTO TJBB_DT_B03115 (SSNY,BBLC,SWJGDM,DJXH,SHXYNO,QYMC,JSMODE,SWJG,TMSE,TSE,MDE,TMSE_LAST,TSE_LAST,MDE_LAST,XH)
    SELECT LC_THISMONTH, '000', V_SWCODE,NULL,NULL,'合计',NULL,NULL,LN_TMSE_HJ, LN_TSE_HJ, LN_MDE_HJ,LN_TMSE_HJ_LAST, LN_TSE_HJ_LAST, LN_MDE_HJ_LAST,NULL
      FROM DUAL;
    COMMIT;

    SELECT SUM(TMSE),SUM(TSE),SUM(MDE),SUM(TMSE_LAST),SUM(TSE_LAST),SUM(MDE_LAST)
      INTO LN_TMSE_HJ, LN_TSE_HJ, LN_MDE_HJ, LN_TMSE_HJ_LAST, LN_TSE_HJ_LAST, LN_MDE_HJ_LAST
      FROM TJBB_DT_B03115 A
     WHERE A.SWJGDM IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))
       AND A.SSNY=LC_THISMONTH
       AND A.BBLC='100';
    INSERT INTO TJBB_DT_B03115 (SSNY,BBLC,SWJGDM,DJXH,SHXYNO,QYMC,JSMODE,SWJG,TMSE,TSE,MDE,TMSE_LAST,TSE_LAST,MDE_LAST,XH)
    SELECT LC_THISMONTH, '100', V_SWCODE,NULL,NULL,'生产小计',NULL,NULL,LN_TMSE_HJ, LN_TSE_HJ, LN_MDE_HJ,LN_TMSE_HJ_LAST, LN_TSE_HJ_LAST, LN_MDE_HJ_LAST,NULL
      FROM DUAL;
    COMMIT;

    SELECT LN_TMSE_HJ - SUM(A.TMSE), LN_TSE_HJ - SUM(A.TSE), LN_MDE_HJ - SUM(A.MDE), 
           LN_TMSE_HJ_LAST - SUM(A.TMSE_LAST), LN_TSE_HJ_LAST - SUM(A.TSE_LAST), LN_MDE_HJ_LAST - SUM(A.MDE_LAST)
      INTO LN_TMSE_OTHER, LN_TSE_OTHER, LN_MDE_OTHER, LN_TMSE_OTHER_LAST, LN_TSE_OTHER_LAST, LN_MDE_OTHER_LAST
      FROM TJBB_DT_B03115 A
     WHERE A.SWJGDM=V_SWCODE AND A.SSNY=LC_THISMONTH AND A.BBLC>'100' AND A.BBLC<'200';
    INSERT INTO TJBB_DT_B03115 (SSNY,BBLC,SWJGDM,DJXH,SHXYNO,QYMC,JSMODE,SWJG,TMSE,TSE,MDE,TMSE_LAST,TSE_LAST,MDE_LAST,XH)
    SELECT LC_THISMONTH, '199', V_SWCODE,NULL,NULL,'生产其他',NULL,NULL,LN_TMSE_OTHER, LN_TSE_OTHER, LN_MDE_OTHER, LN_TMSE_OTHER_LAST, LN_TSE_OTHER_LAST, LN_MDE_OTHER_LAST,NULL
      FROM DUAL;
    COMMIT;

    SELECT SUM(TMSE),SUM(TSE),SUM(MDE),SUM(TMSE_LAST),SUM(TSE_LAST),SUM(MDE_LAST)
      INTO LN_TMSE_HJ, LN_TSE_HJ, LN_MDE_HJ, LN_TMSE_HJ_LAST, LN_TSE_HJ_LAST, LN_MDE_HJ_LAST
      FROM TJBB_DT_B03115 A
     WHERE A.SWJGDM IN (SELECT SWJG_DM FROM TABLE(TL_ADMIN.FUNC_GET_XJ_SWJG(V_SWCODE)))
       AND A.SSNY=LC_THISMONTH
       AND A.BBLC='200';
    INSERT INTO TJBB_DT_B03115 (SSNY,BBLC,SWJGDM,DJXH,SHXYNO,QYMC,JSMODE,SWJG,TMSE,TSE,MDE,TMSE_LAST,TSE_LAST,MDE_LAST,XH)
    SELECT LC_THISMONTH, '200', V_SWCODE,NULL,NULL,'外贸小计',NULL,NULL,LN_TMSE_HJ, LN_TSE_HJ, LN_MDE_HJ,LN_TMSE_HJ_LAST, LN_TSE_HJ_LAST, LN_MDE_HJ_LAST,NULL
      FROM DUAL;
    COMMIT;
    
    SELECT LN_TMSE_HJ - SUM(A.TMSE), LN_TSE_HJ - SUM(A.TSE), LN_MDE_HJ - SUM(A.MDE), 
           LN_TMSE_HJ_LAST - SUM(A.TMSE_LAST), LN_TSE_HJ_LAST - SUM(A.TSE_LAST), LN_MDE_HJ_LAST - SUM(A.MDE_LAST)
      INTO LN_TMSE_OTHER, LN_TSE_OTHER, LN_MDE_OTHER, LN_TMSE_OTHER_LAST, LN_TSE_OTHER_LAST, LN_MDE_OTHER_LAST
      FROM TJBB_DT_B03115 A
     WHERE A.SWJGDM=V_SWCODE AND A.SSNY=LC_THISMONTH AND A.BBLC>'200';
    INSERT INTO TJBB_DT_B03115 (SSNY,BBLC,SWJGDM,DJXH,SHXYNO,QYMC,JSMODE,SWJG,TMSE,TSE,MDE,TMSE_LAST,TSE_LAST,MDE_LAST,XH)
    SELECT LC_THISMONTH, '299', V_SWCODE,NULL,NULL,'外贸其他',NULL,NULL,LN_TMSE_OTHER, LN_TSE_OTHER, LN_MDE_OTHER, LN_TMSE_OTHER_LAST, LN_TSE_OTHER_LAST, LN_MDE_OTHER_LAST,NULL
      FROM DUAL;
    COMMIT;

    UPDATE TJBB_DT_B03115
       SET TMSE_TB = CASE WHEN NVL(TMSE_LAST,0)=0 THEN NULL ELSE ROUND(100 * TMSE / TMSE_LAST -100,1) END
     WHERE SWJGDM=V_SWCODE
       AND SSNY=LC_THISMONTH
       AND BBLC IN ('000','100','199','200','299');
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --4、汇总栏初始化
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B03115 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B03115' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

