prompt Creating procedure PRO_TJBB_DT_B07101_CSH_NEW
prompt =============================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_DT_B07101_CSH_NEW
/*
 * 202210，新增
 * 列参考B01109，行参考B01100（将第39行提到11行，原11-38行依次下移一行）
 * 20260116，根据舟山反馈问题分析，在统计生产企业申报户数、申报出口额、申报免抵退税额口径，提取进料加工数据时加调整数不为0的条件
 */
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY IN VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LD_SYSDATE       DATE;
  LC_THISMONTH     VARCHAR2(6);
  LD_THISYEAR      DATE;
  LD_NEXTMONTH     DATE;
  LC_LASTMONTH     VARCHAR2(6);

  LN_BAHS          NUMBER(10);
  LN_SBHS          NUMBER(10);
  LN_SB_CKE        NUMBER(18,6);

  LN_SB_ZZS        NUMBER(18,6);
  LN_SH_ZZS        NUMBER(18,6);
  LN_SP_ZZS        NUMBER(18,6);
  LN_BL_ZZS        NUMBER(18,6);
  TSFN_ZZS         NUMBER(18,6);

  LN_SB_XFS        NUMBER(18,6);
  LN_SH_XFS        NUMBER(18,6);
  LN_SP_XFS        NUMBER(18,6);
  LN_BL_XFS        NUMBER(18,6);
  TSFN_XFS         NUMBER(18,6);

  LC_SQL           VARCHAR2(4000);
  LC_SQL_UPDATEHZ  VARCHAR2(4000);
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=TRUNC(SYSDATE,'MM');
  END IF;
  LC_THISMONTH :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LD_THISYEAR  :=TRUNC(LD_SYSDATE,'YY');
  LD_NEXTMONTH :=TRUNC(ADD_MONTHS(LD_SYSDATE,1),'MM');
  LC_LASTMONTH :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-12),'YYYYMM');

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_DT_B07101 WHERE SWJGDM=V_SWCODE AND SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
      RETURN;
  END;

  --1、外贸企业
  BEGIN
    --备案户数
    SELECT COUNT(1)
      INTO LN_BAHS
      FROM TL_TSSH.GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR='10';

    --申报户数、申报出口额
    SELECT COUNT(DISTINCT DJXH), ROUND(NVL(SUM(MYLAJ),0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE
     FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MTS_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('10','40','50')
           ) T;

    --申报退税额
    SELECT ROUND(NVL(SUM(CASE WHEN SZ='V' THEN TSE ELSE 0 END),0)/10000,6), 
           ROUND(NVL(SUM(CASE WHEN SZ='C' THEN TSE ELSE 0 END),0)/10000,6) 
      INTO LN_SB_ZZS, LN_SB_XFS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.SZ,C.TSE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MTS_JHMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('10','40','50')
           ) T;

    --审核通过退税额
    SELECT ROUND(NVL(SUM(T.FS_ZZSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.FS_XFSTSE),0)/10000,6) 
      INTO LN_SH_ZZS, LN_SH_XFS
      FROM TL_TSSH.CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC = '10';

    --审批退税额
    SELECT ROUND(NVL(SUM(T.SEHZ_ZZSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.SEHZ_XFSTSE),0)/10000,6)
      INTO LN_SP_ZZS, LN_SP_XFS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.SEHZRQ>=LD_THISYEAR AND T.SEHZRQ<LD_NEXTMONTH
       AND T.LCTJJC='10';

    --国库办理退税额
    SELECT ROUND(NVL(SUM(T.GKBL_ZZSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.GKBL_XFSTSE),0)/10000,6)
      INTO LN_BL_ZZS, LN_BL_XFS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.CKTMSJHSSSWJGDM=V_SWCODE
       AND T.XHRQ_TK>=LD_THISYEAR AND T.XHRQ_TK<LD_NEXTMONTH
       AND T.LCTJJC='10';

    --返纳
    SELECT NVL(ROUND(SUM(CASE WHEN T.ZSXM_DM='10101' THEN T.SJJE ELSE 0 END)/10000,6),0),
           NVL(ROUND(SUM(CASE WHEN T.ZSXM_DM='10102' THEN T.SJJE ELSE 0 END)/10000,6),0)
      INTO TSFN_ZZS, TSFN_XFS
      FROM FG_CKTSFN_HXZG T, TL_TSSH.GLXT_BB_SHXT_DJXX S
     WHERE T.SKSSSWJG_DM=V_SWCODE
       AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
       AND T.YWHZBUUID IS NULL
       AND T.CPCODE=S.CPCODE
       AND S.BAJC_YEAR IN ('00','10');

    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '05', V_SWCODE, LN_BAHS, LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SH_ZZS, LN_SP_ZZS - TSFN_ZZS, LN_BL_ZZS - TSFN_ZZS
      FROM DUAL;
    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '06', V_SWCODE, 0, 0, 0, LN_SB_XFS, LN_SH_XFS, LN_SP_XFS - TSFN_XFS, LN_BL_XFS - TSFN_XFS
      FROM DUAL;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  --2、外综服企业
  BEGIN
    --备案户数
    SELECT COUNT(1)
      INTO LN_BAHS
      FROM TL_TSSH.GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR IN ('70','71','72');

    --申报户数、申报出口额
    SELECT COUNT(DISTINCT DJXH), 
           ROUND(NVL(SUM(MYLAJ),0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MTS_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('70','71')
             UNION ALL
            SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_WZF_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '72'
           ) T;

    --申报退税额
    SELECT ROUND(NVL(SUM(CASE WHEN SZ='V' THEN TSE ELSE 0 END),0)/10000,6), 
           ROUND(NVL(SUM(CASE WHEN SZ='C' THEN TSE ELSE 0 END),0)/10000,6) 
      INTO LN_SB_ZZS, LN_SB_XFS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.SZ,C.TSE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MTS_JHMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('70','71')
             UNION ALL
            SELECT A.DJXH,C.LCSLID,C.SBXH,'V' AS SZ,C.TSE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_WZF_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '72'
           ) T;

    --审核通过退税额
    SELECT ROUND(NVL(SUM(T.FS_ZZSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.FS_XFSTSE),0)/10000,6) 
      INTO LN_SH_ZZS, LN_SH_XFS
      FROM TL_TSSH.CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC IN ('70','71','72');

    --审批退税额
    SELECT ROUND(NVL(SUM(T.SEHZ_ZZSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.SEHZ_XFSTSE),0)/10000,6)
      INTO LN_SP_ZZS, LN_SP_XFS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.SEHZRQ>=LD_THISYEAR AND T.SEHZRQ<LD_NEXTMONTH
       AND T.LCTJJC IN ('70','71','72');

    --国库办理退税额
    SELECT ROUND(NVL(SUM(T.GKBL_ZZSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.GKBL_XFSTSE),0)/10000,6)
      INTO LN_BL_ZZS, LN_BL_XFS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.CKTMSJHSSSWJGDM=V_SWCODE
       AND T.XHRQ_TK>=LD_THISYEAR AND T.XHRQ_TK<LD_NEXTMONTH
       AND T.LCTJJC IN ('70','71','72');

    --返纳
    SELECT NVL(ROUND(SUM(CASE WHEN T.ZSXM_DM='10101' THEN T.SJJE ELSE 0 END)/10000,6),0),
           NVL(ROUND(SUM(CASE WHEN T.ZSXM_DM='10102' THEN T.SJJE ELSE 0 END)/10000,6),0)
      INTO TSFN_ZZS, TSFN_XFS
      FROM FG_CKTSFN_HXZG T, TL_TSSH.GLXT_BB_SHXT_DJXX S
     WHERE T.SKSSSWJG_DM=V_SWCODE
       AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
       AND T.YWHZBUUID IS NULL
       AND T.CPCODE=S.CPCODE
       AND S.BAJC_YEAR IN ('70','71','72');

    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '08', V_SWCODE, LN_BAHS, LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SH_ZZS, LN_SP_ZZS - TSFN_ZZS, LN_BL_ZZS - TSFN_ZZS
      FROM DUAL;
    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '09', V_SWCODE, 0, 0, 0, LN_SB_XFS, LN_SH_XFS, LN_SP_XFS - TSFN_XFS, LN_BL_XFS - TSFN_XFS
      FROM DUAL;
    COMMIT;

    --2.1 符合13号公告规定业务
    --备案户数
    SELECT COUNT(1)
      INTO LN_BAHS
      FROM TL_TSSH.GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR IN ('70','71');

    --申报户数、申报出口额
    SELECT COUNT(DISTINCT DJXH), 
           ROUND(NVL(SUM(MYLAJ),0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MTS_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '71'
           ) T;

    --申报退税额
    SELECT ROUND(NVL(SUM(TSE),0)/10000,6)
      INTO LN_SB_ZZS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.SZ,C.TSE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MTS_JHMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '71'
           ) T;

    --审核通过退税额
    SELECT ROUND(NVL(SUM(T.FS_ZZSTSE+T.FS_XFSTSE),0)/10000,6) 
      INTO LN_SH_ZZS
      FROM TL_TSSH.CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC = '71';

    --审批退税额
    SELECT ROUND(NVL(SUM(T.SEHZ_ZZSTSE+T.SEHZ_XFSTSE),0)/10000,6)
      INTO LN_SP_ZZS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.SEHZRQ>=LD_THISYEAR AND T.SEHZRQ<LD_NEXTMONTH
       AND T.LCTJJC = '71';

    --国库办理退税额
    SELECT ROUND(NVL(SUM(T.GKBL_ZZSTSE+T.GKBL_XFSTSE),0)/10000,6)
      INTO LN_BL_ZZS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.CKTMSJHSSSWJGDM=V_SWCODE
       AND T.XHRQ_TK>=LD_THISYEAR AND T.XHRQ_TK<LD_NEXTMONTH
       AND T.LCTJJC = '71';

    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '10', V_SWCODE, LN_BAHS, LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SH_ZZS, LN_SP_ZZS, LN_BL_ZZS
      FROM DUAL;
    COMMIT;

    --2.2 符合35号公告规定业务
    --备案户数
    SELECT COUNT(1)
      INTO LN_BAHS
      FROM TL_TSSH.GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR IN ('71','72');

    --申报户数、申报出口额
    SELECT COUNT(DISTINCT DJXH), 
           ROUND(NVL(SUM(MYLAJ),0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_WZF_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '72'
           ) T;

    --申报退税额
    SELECT ROUND(NVL(SUM(TSE),0)/10000,6)
      INTO LN_SB_ZZS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,'V' AS SZ,C.TSE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_WZF_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '72'
           ) T;

    --审核通过退税额
    SELECT ROUND(NVL(SUM(T.FS_ZZSTSE+T.FS_XFSTSE),0)/10000,6) 
      INTO LN_SH_ZZS
      FROM TL_TSSH.CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC = '72';

    --审批退税额
    SELECT ROUND(NVL(SUM(T.SEHZ_ZZSTSE+T.SEHZ_XFSTSE),0)/10000,6)
      INTO LN_SP_ZZS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.SEHZRQ>=LD_THISYEAR AND T.SEHZRQ<LD_NEXTMONTH
       AND T.LCTJJC = '72';

    --国库办理退税额
    SELECT ROUND(NVL(SUM(T.GKBL_ZZSTSE+T.GKBL_XFSTSE),0)/10000,6)
      INTO LN_BL_ZZS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.CKTMSJHSSSWJGDM=V_SWCODE
       AND T.XHRQ_TK>=LD_THISYEAR AND T.XHRQ_TK<LD_NEXTMONTH
       AND T.LCTJJC = '72';

    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '11', V_SWCODE, LN_BAHS, LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SH_ZZS, LN_SP_ZZS, LN_BL_ZZS
      FROM DUAL;
    COMMIT;

  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  --3、生产企业
  BEGIN
    --3.1、自营出口的生产企业
    --备案户数
    SELECT COUNT(1)
      INTO LN_BAHS
      FROM TL_TSSH.GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR='21';

    --申报户数、申报出口额、申报免抵退税额
    SELECT COUNT(DISTINCT DJXH), 
           ROUND(NVL(SUM(MYLAJ),0)/10000,6),
           ROUND(NVL(SUM(TSE),0)/10000,6),
           ROUND(NVL(SUM(MDE),0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SB_XFS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ,
                   C.MDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_ZZSTSE/A.SB_MDTSE END) AS TSE,
                   C.MDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_MDSE  /A.SB_MDTSE END) AS MDE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MDT_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('21','41','51','61')
             UNION ALL
            SELECT A.DJXH,C.LCSLID,'00000000' AS SBXH,0 AS MYLAJ,
                   C.JLJGHXYTZMDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_ZZSTSE/A.SB_MDTSE END) AS TSE,
                   C.JLJGHXYTZMDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_MDSE  /A.SB_MDTSE END) AS MDE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MDT_SBDSHZ C ON C.LCSLID=B.LCSLID AND C.JLJGHXYTZMDTSE<>0
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('21','41','51','61')
           ) T;

    --审核通过免抵退税额
    SELECT ROUND(NVL(SUM(T.FS_ZZSTSE+T.FS_XFSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.FS_MDSE),0)/10000,6) 
      INTO LN_SH_ZZS, LN_SH_XFS
      FROM TL_TSSH.CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC = '21';

    --审批免抵退税额
    SELECT ROUND(NVL(SUM(T.SEHZ_ZZSTSE + T.SEHZ_XFSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.SEHZ_MDSE),0)/10000,6)
      INTO LN_SP_ZZS, LN_SP_XFS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.SEHZRQ>=LD_THISYEAR AND T.SEHZRQ<LD_NEXTMONTH
       AND T.LCTJJC = '21';

    --国库办理免抵退税额
    SELECT ROUND(NVL(SUM(T.GKBL_ZZSTSE+T.GKBL_XFSTSE),0)/10000,6)
      INTO LN_BL_ZZS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.CKTMSJHSSSWJGDM=V_SWCODE
       AND T.XHRQ_TK>=LD_THISYEAR AND T.XHRQ_TK<LD_NEXTMONTH
       AND T.LCTJJC = '21';
    SELECT ROUND(NVL(SUM(T.GKBL_MDSE),0)/10000,6)
      INTO LN_BL_XFS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.MDTKSSSWJGDM=V_SWCODE
       AND T.XHRQ_MD>=LD_THISYEAR AND T.XHRQ_MD<LD_NEXTMONTH
       AND T.LCTJJC = '21';

    --返纳
    SELECT NVL(ROUND(SUM(T.SJJE)/10000,6),0)
      INTO TSFN_ZZS
      FROM FG_CKTSFN_HXZG T, TL_TSSH.GLXT_BB_SHXT_DJXX S
     WHERE T.SKSSSWJG_DM=V_SWCODE
       AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
       AND T.YWHZBUUID IS NULL
       AND T.CPCODE=S.CPCODE
       AND S.BAJC_YEAR = '21';

    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '17', V_SWCODE, LN_BAHS, LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SH_ZZS, LN_SP_ZZS - TSFN_ZZS, LN_BL_ZZS - TSFN_ZZS
      FROM DUAL;
    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '18', V_SWCODE, 0, 0, 0, LN_SB_XFS, LN_SH_XFS, LN_SP_XFS, LN_BL_XFS
      FROM DUAL;
    COMMIT;

    --3.2、委托出口的生产企业
    --备案户数
    SELECT COUNT(1)
      INTO LN_BAHS
      FROM TL_TSSH.GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR='22';

    --申报户数、申报出口额、申报免抵退税额
    SELECT COUNT(DISTINCT DJXH), 
           ROUND(NVL(SUM(MYLAJ),0)/10000,6),
           ROUND(NVL(SUM(TSE),0)/10000,6),
           ROUND(NVL(SUM(MDE),0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SB_XFS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ,
                   C.MDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_ZZSTSE/A.SB_MDTSE END) AS TSE,
                   C.MDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_MDSE  /A.SB_MDTSE END) AS MDE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MDT_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('22','42','52','62')
             UNION ALL
            SELECT A.DJXH,C.LCSLID,'00000000' AS SBXH,0 AS MYLAJ,
                   C.JLJGHXYTZMDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_ZZSTSE/A.SB_MDTSE END) AS TSE,
                   C.JLJGHXYTZMDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_MDSE  /A.SB_MDTSE END) AS MDE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MDT_SBDSHZ C ON C.LCSLID=B.LCSLID AND C.JLJGHXYTZMDTSE<>0
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('22','42','52','62')
           ) T;

    --审核通过免抵退税额
    SELECT ROUND(NVL(SUM(T.FS_ZZSTSE+T.FS_XFSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.FS_MDSE),0)/10000,6) 
      INTO LN_SH_ZZS, LN_SH_XFS
      FROM TL_TSSH.CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC = '22';

    --审批免抵退税额
    SELECT ROUND(NVL(SUM(T.SEHZ_ZZSTSE + T.SEHZ_XFSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.SEHZ_MDSE),0)/10000,6)
      INTO LN_SP_ZZS, LN_SP_XFS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.SEHZRQ>=LD_THISYEAR AND T.SEHZRQ<LD_NEXTMONTH
       AND T.LCTJJC = '22';

    --国库办理免抵退税额
    SELECT ROUND(NVL(SUM(T.GKBL_ZZSTSE+T.GKBL_XFSTSE),0)/10000,6)
      INTO LN_BL_ZZS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.CKTMSJHSSSWJGDM=V_SWCODE
       AND T.XHRQ_TK>=LD_THISYEAR AND T.XHRQ_TK<LD_NEXTMONTH
       AND T.LCTJJC = '22';
    SELECT ROUND(NVL(SUM(T.GKBL_MDSE),0)/10000,6)
      INTO LN_BL_XFS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.MDTKSSSWJGDM=V_SWCODE
       AND T.XHRQ_MD>=LD_THISYEAR AND T.XHRQ_MD<LD_NEXTMONTH
       AND T.LCTJJC = '22';

    --返纳
    SELECT NVL(ROUND(SUM(T.SJJE)/10000,6),0)
      INTO TSFN_ZZS
      FROM FG_CKTSFN_HXZG T, TL_TSSH.GLXT_BB_SHXT_DJXX S
     WHERE T.SKSSSWJG_DM=V_SWCODE
       AND T.RKRQ>=LD_THISYEAR AND T.RKRQ<LD_NEXTMONTH
       AND T.YWHZBUUID IS NULL
       AND T.CPCODE=S.CPCODE
       AND S.BAJC_YEAR = '22';

    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '20', V_SWCODE, LN_BAHS, LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SH_ZZS, LN_SP_ZZS - TSFN_ZZS, LN_BL_ZZS - TSFN_ZZS
      FROM DUAL;
    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '21', V_SWCODE, 0, 0, 0, LN_SB_XFS, LN_SH_XFS, LN_SP_XFS, LN_BL_XFS
      FROM DUAL;
    COMMIT;

    --3.3、外商投资的生产企业
    --备案户数
    SELECT COUNT(1)
      INTO LN_BAHS
      FROM TL_TSSH.GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR='23';

    --申报户数、申报出口额、申报免抵退税额
    SELECT COUNT(DISTINCT DJXH), 
           ROUND(NVL(SUM(MYLAJ),0)/10000,6),
           ROUND(NVL(SUM(TSE),0)/10000,6),
           ROUND(NVL(SUM(MDE),0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SB_XFS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.MYLAJ,
                   C.MDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_ZZSTSE/A.SB_MDTSE END) AS TSE,
                   C.MDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_MDSE  /A.SB_MDTSE END) AS MDE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MDT_CKMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('23','43','53','63')
             UNION ALL
            SELECT A.DJXH,C.LCSLID,'00000000' AS SBXH,0 AS MYLAJ,
                   C.JLJGHXYTZMDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_ZZSTSE/A.SB_MDTSE END) AS TSE,
                   C.JLJGHXYTZMDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_MDSE  /A.SB_MDTSE END) AS MDE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MDT_SBDSHZ C ON C.LCSLID=B.LCSLID AND C.JLJGHXYTZMDTSE<>0
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('23','43','53','63')
           ) T;

    --审核通过免抵退税额
    SELECT ROUND(NVL(SUM(T.FS_ZZSTSE+T.FS_XFSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.FS_MDSE),0)/10000,6) 
      INTO LN_SH_ZZS, LN_SH_XFS
      FROM TL_TSSH.CKTS_LC_YWHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.FSRQ>=LD_THISYEAR AND T.FSRQ<LD_NEXTMONTH
       AND T.LCTJJC = '23';

    --审批免抵退税额
    SELECT ROUND(NVL(SUM(T.SEHZ_ZZSTSE + T.SEHZ_XFSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.SEHZ_MDSE),0)/10000,6)
      INTO LN_SP_ZZS, LN_SP_XFS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.TSSWJG_DM=V_SWCODE
       AND T.SEHZRQ>=LD_THISYEAR AND T.SEHZRQ<LD_NEXTMONTH
       AND T.LCTJJC = '23';

    --国库办理免抵退税额
    SELECT ROUND(NVL(SUM(T.GKBL_ZZSTSE+T.GKBL_XFSTSE),0)/10000,6)
      INTO LN_BL_ZZS
      FROM TL_TSSH.CKTS_LC_SEHZXX T
     WHERE T.CKTMSJHSSSWJGDM=V_SWCODE
       AND T.XHRQ_TK>=LD_THISYEAR AND T.XHRQ_TK<LD_NEXTMONTH
