    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
