  --4、服务贸易
  BEGIN
    --4.1、国际运输服务
    --备案户数
    SELECT COUNT(1)
      INTO LN_BAHS
      FROM TL_TSSH.GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR='60';

    --申报户数、申报出口额、申报免抵退税额
    SELECT COUNT(DISTINCT DJXH), 
           ROUND(NVL(SUM(MYLAJ),0)/10000,6),
           ROUND(NVL(SUM(TSE),0)/10000,6),
           ROUND(NVL(SUM(MDE),0)/10000,6)
      INTO LN_SBHS, LN_SB_CKE, LN_SB_ZZS, LN_SB_XFS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.YSFWYYEMY AS MYLAJ,
                   C.MDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_ZZSTSE/A.SB_MDTSE END) AS TSE,
                   C.MDTSE * (CASE WHEN A.SB_MDTSE=0 THEN 1 ELSE A.SB_MDSE  /A.SB_MDTSE END) AS MDE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_MDT_GJYS C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC IN ('61','62','63')
           ) T;

    --审核通过免抵退税额
    SELECT ROUND(NVL(SUM(T.FS_ZZSTSE+T.FS_XFSTSE),0)/10000,6), 
           ROUND(NVL(SUM(T.FS_MDSE),0)/10000,6) 
      INTO LN_SH_ZZS, LN_SH_XFS
