    SELECT COUNT(1)
      INTO LN_BAHS
      FROM TL_TSSH.GLXT_BB_SHXT_DJXX T
     WHERE T.SWJGDM=V_SWCODE
       AND T.ZX_FLAG='N'
       AND T.BAJC_YEAR='30';

    --申报户数、申报出口额、申报免抵退税额
    SELECT COUNT(DISTINCT DJXH), 
           ROUND(NVL(SUM(TSE),0)/10000,6)
      INTO LN_SBHS, LN_SB_ZZS
      FROM (SELECT A.DJXH,C.LCSLID,C.SBXH,C.XFSTSE AS TSE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_FZC_SBMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
               AND A.QDSJ>=LD_THISYEAR AND A.QDSJ<LD_NEXTMONTH
               AND B.LCTJJC = '30'
             UNION ALL
            SELECT A.DJXH,C.LCSLID,C.SBXH,C.TSE
              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_GJ_SBMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
