              FROM TL_TSSH.CKTS_LC_SBXX A
             INNER JOIN TL_TSSH.CKTS_LC_SHXX B ON B.LCSLID_SB=A.LCSLID_SB
             INNER JOIN TL_TSSH.CKTS_SB_YS_SBMX C ON C.LCSLID=B.LCSLID AND C.BYBLBZ='N'
             WHERE A.TSSWJG_DM=V_SWCODE
