  --6、计算行
  BEGIN
    FOR LSF_XX IN (SELECT TRIM(TO_CHAR(SUBSTR(T.FORMULA,2,INSTR(T.FORMULA,')')-2),'00')) AS BBLC,
                          '('||REPLACE(REPLACE(REPLACE(SUBSTR(T.FORMULA,INSTR(T.FORMULA,'=')+1),'(',''''),'+',','),')','''')||')' AS BBCS
                     FROM TJBB_REPORT_FORMULA T
                    WHERE T.BBDM='B07101'
                      AND T.TYPE=2
                      AND T.FORMULA<>'(15)=100 *(13)/(14)'
                    ORDER BY T.YXJ)
    LOOP
      BEGIN
        LC_SQL := 'INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
                   SELECT '''||LC_THISMONTH||''', '''||LSF_XX.BBLC||''', '''||V_SWCODE||''', SUM(RDHS), SUM(SBHS),
                          SUM(SB_CKE_CUR), SUM(SB_TMSE_CUR), SUM(SH_TMSE_CUR), SUM(SP_TMSE_CUR), SUM(TK_CUR)
                     FROM TJBB_DT_B07101
                    WHERE SWJGDM='''||V_SWCODE||'''
                      AND SSNY='''||LC_THISMONTH||'''
                      AND TRIM(TO_CHAR(TO_NUMBER(BBLC))) IN '||LSF_XX.BBCS;

        EXECUTE IMMEDIATE LC_SQL;
        COMMIT;
      END;
    END LOOP;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  --7、计算15行
  BEGIN
    INSERT INTO TJBB_DT_B07101 (SSNY, BBLC, SWJGDM, RDHS, SBHS, SB_CKE_CUR, SB_TMSE_CUR, SH_TMSE_CUR, SP_TMSE_CUR, TK_CUR)
    SELECT LC_THISMONTH, '15', V_SWCODE, NULL, NULL, NULL, 
           CASE WHEN B.SB_TMSE_CUR=0 THEN 0 ELSE 100 * A.SB_TMSE_CUR/B.SB_TMSE_CUR END,
           CASE WHEN B.SH_TMSE_CUR=0 THEN 0 ELSE 100 * A.SH_TMSE_CUR/B.SH_TMSE_CUR END,
           CASE WHEN B.SP_TMSE_CUR=0 THEN 0 ELSE 100 * A.SP_TMSE_CUR/B.SP_TMSE_CUR END,
           CASE WHEN B.TK_CUR=0 THEN 0 ELSE 100 * A.TK_CUR/B.TK_CUR END
      FROM TJBB_DT_B07101 A,
           TJBB_DT_B07101 B
     WHERE A.SWJGDM=V_SWCODE
       AND A.SSNY=LC_THISMONTH
       AND A.BBLC='13'
       AND B.SWJGDM=V_SWCODE
       AND B.SSNY=LC_THISMONTH
       AND B.BBLC='14';
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  --8、更新上年同期列
  BEGIN
    UPDATE TJBB_DT_B07101 T
       SET (SB_CKE_LAST, SB_TMSE_LAST, SH_TMSE_LAST, SP_TMSE_LAST, TK_LAST)=
           (SELECT NVL(SB_CKE_CUR,0), NVL(SB_TMSE_CUR,0), NVL(SH_TMSE_CUR,0), NVL(SP_TMSE_CUR,0), NVL(TK_CUR,0)
              FROM TJBB_DT_B07101 B
             WHERE B.SWJGDM=V_SWCODE
               AND B.SSNY=LC_LASTMONTH
               AND B.BBLC=T.BBLC)
     WHERE T.SWJGDM=V_SWCODE
       AND T.SSNY=LC_THISMONTH;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  --9、更新占比、同比列
  BEGIN
    UPDATE TJBB_DT_B07101 T
       SET RD_SB_LV     = CASE WHEN T.RDHS=0         THEN 0 ELSE 100 * T.SBHS/T.RDHS                    END,
           SB_CKE_TBLV  = CASE WHEN T.SB_CKE_LAST=0  THEN 0 ELSE 100 * T.SB_CKE_CUR/T.SB_CKE_LAST -100   END,
           SB_TMSE_TBLV = CASE WHEN T.SB_TMSE_LAST=0 THEN 0 ELSE 100 * T.SB_TMSE_CUR/T.SB_TMSE_LAST -100 END,
           SH_TMSE_TBLV = CASE WHEN T.SH_TMSE_LAST=0 THEN 0 ELSE 100 * T.SH_TMSE_CUR/T.SH_TMSE_LAST -100 END,
           SP_TMSE_TBLV = CASE WHEN T.SP_TMSE_LAST=0 THEN 0 ELSE 100 * T.SP_TMSE_CUR/T.SP_TMSE_LAST -100 END,
           TK_TBLV      = CASE WHEN T.TK_LAST=0      THEN 0 ELSE 100 * T.TK_CUR/T.TK_LAST -100           END
     WHERE T.SWJGDM=V_SWCODE
       AND T.SSNY=LC_THISMONTH
       AND T.BBLC<>'15';
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  --10、更新汇总列
  BEGIN
    LC_SQL_UPDATEHZ := 'UPDATE TJBB_DT_B07101 SET ';

    FOR LSF_XX IN (SELECT FNAME FROM TJBB_HEADER_COLS WHERE BBDM='B07101' AND FTYPE='NUMBER' ORDER BY SHOWORDER)
    LOOP
      LC_SQL_UPDATEHZ := LC_SQL_UPDATEHZ || LSF_XX.FNAME || '_HZ=' || LSF_XX.FNAME || ', ';
    END LOOP;

    LC_SQL_UPDATEHZ := SUBSTR(LC_SQL_UPDATEHZ, 1, LENGTH(LC_SQL_UPDATEHZ)-2) ||
                       ' WHERE SWJGDM=''' || V_SWCODE || ''' AND SSNY=''' || LC_THISMONTH || '''';

    EXECUTE IMMEDIATE LC_SQL_UPDATEHZ;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;

  RETURN;
END;
/

