prompt Creating procedure PRO_TJBB_CHECK_DTBB
prompt ======================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_CHECK_DTBB
/****************************************************
 * 报表上报前的表间逻辑关系检查
 ***************************************************/
(
  V_SWCODE  IN  VARCHAR2,
  V_SSNY    IN  VARCHAR2,
  V_BBDLDM  IN  VARCHAR2,
  V_ERROR   OUT NUMBER,
  V_MSG     OUT VARCHAR2
)
AS
  LD_SYSDATE       DATE;
  LC_THISMONTH     VARCHAR2(6);
  LC_PREVMONTH     VARCHAR2(6);

  LN_AMT_TARGET    NUMBER(16,4);
  LN_AMT_REFER     NUMBER(16,4);
BEGIN
  V_ERROR :=0;
  V_MSG   := ' ';

  IF V_SSNY IS NOT NULL THEN
    LD_SYSDATE:=TO_DATE(V_SSNY||'01','YYYYMMDD');
  ELSE
    LD_SYSDATE:=SYSDATE;
  END IF;
  LC_THISMONTH   :=TO_CHAR(LD_SYSDATE,'YYYYMM');
  LC_PREVMONTH   :=TO_CHAR(ADD_MONTHS(LD_SYSDATE,-1),'YYYYMM');

  --0、清除原有制表数据，准备重新制表
  BEGIN
    DELETE FROM TJBB_SB_JYXX WHERE SWJGDM=V_SWCODE AND BBDLDM=V_BBDLDM;
    COMMIT;
  EXCEPTION
    WHEN OTHERS THEN
      V_ERROR := SQLCODE;
      V_MSG   := SQLERRM;
  END;
  IF V_ERROR <> 0 THEN
    RETURN;
  END IF;

  IF V_BBDLDM='B01' THEN
    BEGIN
      SELECT T.ZH_TMSE_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.HJ_TSE
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01101 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,暂缓办理退（免）税额小计应与附表《暂缓退（免）税统计月报表》对应栏一致'
               FROM DUAL;
        COMMIT;
      END IF;
      
      SELECT T.BY_TMSE_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.HJ_TSE
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01102 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,不予办理退（免）税额小计应与附表《不予办理退（免）税统计月报表》对应栏一致'
               FROM DUAL;
        COMMIT;
      END IF;

      SELECT T.RDHS
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.RDHS
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01108 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>0 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,备案户数应与《出口退（免）税情况分析月报表（本月情况）》对应栏一致'
               FROM DUAL;
        COMMIT;
      END IF;
      SELECT T.RDHS
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>0 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,备案户数应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
               FROM DUAL;
        COMMIT;
      END IF;
      
      SELECT T.SBHS
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.SBHS
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>0 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,申报户数应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
               FROM DUAL;
        COMMIT;
      END IF;
      
      SELECT T.SB_CKE_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.SB_CKE_XJ
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,申报退税出口额应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
               FROM DUAL;
        COMMIT;
      END IF;
      
      SELECT T.SB_TMSE_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.SB_TMSE_XJ
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,申报退（免）税额应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
               FROM DUAL;
        COMMIT;
      END IF;
      
      SELECT T.SH_TMSE_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.SH_TMSE_XJ
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,审核通过应退（免）税额应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
               FROM DUAL;
        COMMIT;
      END IF;
      
      SELECT T.SP_TK_XJ
        INTO LN_AMT_TARGET
        FROM TJBB_DT_B01100 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      SELECT T.SP_TMSE_XJ
        INTO LN_AMT_REFER
        FROM TJBB_DT_B01109 T
       WHERE T.SWJGDM=V_SWCODE AND T.SSNY=LC_THISMONTH AND T.BBLC='01';
      IF ROUND(ABS(LN_AMT_TARGET - LN_AMT_REFER),0)>2 THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,审批应退（免）税额应与《出口退（免）税情况分析月报表（累计情况）》对应栏一致'
