             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','出口退（免）税情况分析月报表（主表）,外综服企业国库已办理退（调）库额应与《外贸综合服务企业退税情况统计表》外综服企业国库已办理退（调）库额一致'
               FROM DUAL;
        COMMIT;
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        INSERT INTO TJBB_SB_JYXX(ID,SWJGDM,SSNY,BBDLDM,BBDM,MSG_TYPE,MSG_LEVEL,MSG)
             SELECT SEQ_TJBB_SB_JYXX.NEXTVAL,V_SWCODE,LC_THISMONTH,V_BBDLDM,'B01100','1','2','总局出口退（免）税月报表 或 总局专项报表 未制表，无法比较勾稽关系！'
               FROM DUAL;
        COMMIT;
    END;
  END IF;
