prompt Creating procedure PRO_TJBB_CSH_B03B07
prompt ======================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_CSH_B03B07
/*
 * 省局月报表/出口退税月报表（不计结转），所有税务局重新制表
 * 需要手工调制报表所属期
 */
(
  LC_MONTH    IN  VARCHAR2
)
AS
  LC_SWJGDM        VARCHAR2(11);
BEGIN
  --区县局
  FOR LSF_SWJG IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1' AND YXWS=7 ORDER BY SWJG_DM) LOOP
    LC_SWJGDM := LSF_SWJG.SWJG_DM;

    PRO_TJBB_B03_CSH(LC_SWJGDM,LC_MONTH);
    UPDATE TJBB_TASK T
       SET T.STATUS='20'
     WHERE T.BBDLDM='B03' AND T.SWJGDM=LC_SWJGDM AND NY=LC_MONTH AND T.STATUS<>'20';
    COMMIT;

    PRO_TJBB_B07_CSH(LC_SWJGDM,LC_MONTH);
    UPDATE TJBB_TASK T
       SET T.STATUS='20'
     WHERE T.BBDLDM='B07' AND T.SWJGDM=LC_SWJGDM AND NY=LC_MONTH AND T.STATUS<>'20';
    COMMIT;
  END LOOP;

  --地市局
  FOR LSF_SWJG IN (SELECT SWJG_DM FROM DM_SWJG WHERE TSJG_BZ='1' AND YXWS=5 ORDER BY SWJG_DM) LOOP
    LC_SWJGDM := LSF_SWJG.SWJG_DM;

    PRO_TJBB_B03_HZ(LC_SWJGDM,LC_MONTH);
    UPDATE TJBB_TASK T
       SET T.STATUS='20'
     WHERE T.BBDLDM='B03' AND T.SWJGDM=LC_SWJGDM AND NY=LC_MONTH AND T.STATUS<>'20';
    COMMIT;

    PRO_TJBB_B07_HZ(LC_SWJGDM,LC_MONTH);
    UPDATE TJBB_TASK T
       SET T.STATUS='20'
     WHERE T.BBDLDM='B07' AND T.SWJGDM=LC_SWJGDM AND NY=LC_MONTH AND T.STATUS<>'20';
    COMMIT;
  END LOOP;

  --省局
  BEGIN
    LC_SWJGDM := '13300000000';
    
    PRO_TJBB_B03_HZ(LC_SWJGDM,LC_MONTH);
    UPDATE TJBB_TASK T
       SET T.STATUS='20'
     WHERE T.BBDLDM='B03' AND T.SWJGDM=LC_SWJGDM AND NY=LC_MONTH AND T.STATUS<>'20';
    COMMIT;

    PRO_TJBB_B07_HZ(LC_SWJGDM,LC_MONTH);
    UPDATE TJBB_TASK T
       SET T.STATUS='20'
     WHERE T.BBDLDM='B07' AND T.SWJGDM=LC_SWJGDM AND NY=LC_MONTH AND T.STATUS<>'20';
    COMMIT;
  END;
END;
/

prompt
prompt Creating procedure PRO_TJBB_CSH_ONESWJG
prompt =======================================
prompt
CREATE OR REPLACE PROCEDURE PRO_TJBB_CSH_ONESWJG
/*
 * 单一局，所有报表重置
 */
(
  LC_SWJGDM  IN  VARCHAR2,
	V_SSNY     IN  VARCHAR2
)
AS
  LC_MONTH         VARCHAR2(6);
BEGIN
  IF V_SSNY IS NOT NULL THEN
    LC_MONTH :=V_SSNY;
  ELSE
    LC_MONTH:= TO_CHAR(ADD_MONTHS(SYSDATE,-1),'YYYYMM');
  END IF;

  --按报表顺序依次制表
  PRO_TJBB_B01_CSH(LC_SWJGDM,LC_MONTH);
  PRO_TJBB_B02_CSH(LC_SWJGDM,LC_MONTH);
  PRO_TJBB_B04_CSH(LC_SWJGDM,LC_MONTH);
  PRO_TJBB_B05_CSH(LC_SWJGDM,LC_MONTH);
  PRO_TJBB_B06_CSH(LC_SWJGDM,LC_MONTH);

  IF SUBSTR(LC_SWJGDM,-6)='000000' THEN
    PRO_TJBB_B03_HZ(LC_SWJGDM,LC_MONTH);
    PRO_TJBB_B07_HZ(LC_SWJGDM,LC_MONTH);
  ELSE
    PRO_TJBB_B03_CSH(LC_SWJGDM,LC_MONTH);
    PRO_TJBB_B07_CSH(LC_SWJGDM,LC_MONTH);
  END IF;

END;
/

