prompt
prompt Creating trigger TRD_FG_SRTHS_QD
prompt ================================
prompt
CREATE OR REPLACE TRIGGER TRD_FG_SRTHS_QD
  before delete
  on tl_admin.FG_SRTHS_QD
  for each row
/*
  declare
  v_yn varchar2(6);
  v_zbjg varchar2(11);
  v_tse number(16,2);
*/
begin
  --指标计划不在管理系统下达，清单生成不做指标监控
  return;
  /*
  if :old.zbjg_dm is null then
    return;
  end if;
  --清单生成后作废删除，回退指标
  if :old.qdbz='0' then
    --清单未生成，不做处理
    return;
  else
    v_tse := :old.zzsamt + :old.xfsamt;
  end if;

  v_yn := to_char(sysdate,'yyyymm');
  if to_char(:old.qd_date,'yyyymm')<>v_yn then
    raise_application_error('-20001','[退还书清单生成日期不在当前系统年月，不允许作废删除！]');
  end if;

  v_zbjg:=:old.zbjg_dm;
  update tl_admin.zb_tsjhzx_hzb set byybltse=byybltse- v_tse
         where zbjg_dm=v_zbjg and tszb_yn=v_yn;
  EXCEPTION
  WHEN no_data_found THEN
    raise_application_error('-20002','[' || v_zbjg||'指标计划不存在，不能作废收入退还书记录！]');
    */
end TRD_FG_SRTHS_QD;
/

