prompt Creating trigger TRI_YJ_SBXX_HZ
prompt ===============================
prompt
CREATE OR REPLACE TRIGGER TRI_YJ_SBXX_HZ
  before insert
  on tl_admin.YJ_SBXX_HZ
  for each row
begin
  if(:new.Sbzt_Dm='20') and (:new.lzhj is null or :new.zzsbb is null)  then
    begin
     :new.Sbzt_Dm:='29';
    end;
  end if;

return ;

end TRI_YJ_SBXX_HZ;
/

prompt
prompt Creating trigger TRU_FG_SRTHS_QD
prompt ================================
prompt
CREATE OR REPLACE TRIGGER tru_fg_srths_qd
  before update
  on TL_ADMIN.FG_SRTHS_QD
  for each row
  /*
  declare
  v_yn varchar2(6);
  v_zbjg varchar2(11);
  v_tse number(16,2);
  */
begin
  --指标计划不在管理系统下达，清单生成不做指标监控
  return;
  /*
  --清单生成，扣减
  if :old.qdbz='0' and :new.qdbz='1' then
    v_tse := :new.zzsamt + :new.xfsamt;
  else
    if:old.qdbz='1' and :new.qdbz='0' then
       v_tse := -(:new.zzsamt + :new.xfsamt);
    else
      --清单标志不变，不做处理
      return;
    end if;
  end if;

  begin
    v_zbjg:=:new.zbjg_dm;
    if v_zbjg is null then
      raise_application_error('-20001','[退税机关'||:new.swjg_dm||'未定义指标机关参数！]');
    end if;
  end;

  v_yn := to_char(sysdate,'yyyymm');

  update tl_admin.zb_tsjhzx_hzb set byybltse=byybltse+ v_tse
         where zbjg_dm=v_zbjg and tszb_yn=v_yn;
  EXCEPTION
  WHEN no_data_found THEN
    raise_application_error('-20001','[指标计划不存在，不能生成清单！]');
  */
end tru_fg_srths_qd;
/

