prompt ===============================
prompt
CREATE OR REPLACE TRIGGER TRU_YJ_SBXX_HZ
  before update
  on tl_admin.YJ_SBXX_HZ
  for each row
begin
  if(:new.Sbzt_Dm='20') and (:new.lzhj is null or :new.zzsbb is null)  then
    begin
     :new.Sbzt_Dm:='29';
    end;
  end if;

return ;

end TRU_YJ_SBXX_HZ;
/

