  for each row
declare
  v_ck_zbjg varchar2(11);
  v_hzbye_rk number(16,2);
  v_hzbye_ck number(16,2);
begin
  if :old.sxbz='1' and :new.sxbz<>'1' then
     raise_application_error('-20001','[已生效的指标计划不允许被撤销生效]');
  end if;
  if :old.zbjg_dm <> :new.zbjg_dm then
     raise_application_error('-20002','[指标税务机关代码不允许被修改]');
  end if;
  if :old.tszb_yn <> :new.tszb_yn then
     raise_application_error('-20002','[指标年月不允许被修改]');
  end if;

  --指标生效，加入对应机关和年月的本月下达数
  if :old.sxbz='0' and :new.sxbz='1' then
    begin
        --下发负数冲红，检查指标余额是否足够
        begin
          select nvl(byjhye,0) into v_hzbye_rk from zb_tsjhzx_hzb
                 where zbjg_dm=:new.zbjg_dm and tszb_yn=:new.tszb_yn;
          EXCEPTION
          WHEN no_data_found THEN
            raise_application_error('-20002','[指标年月' || :new.tszb_yn || '尚未创建汇总表，不允许下达计划。]');
        end;

        if :new.tszbje<0 and (v_hzbye_rk + :new.tszbje)<0 then
           raise_application_error('-20002','[入库机关' || :new.zbjg_dm || '的指标余额('|| v_hzbye_rk ||')不足回退冲红。]');
        end if;
        --市局下发，检查出口指标余额是否足够分配
        select ck_zbjg into v_ck_zbjg from dm_zbjg where zbjg_dm=:new.zbjg_dm;
        if v_ck_zbjg is not null then
          --指标机关有定义出口机关，则需要从出口机关扣除相应的指标。
          begin
            select nvl(byjhye,0) into v_hzbye_ck from zb_tsjhzx_hzb
                   where zbjg_dm=v_ck_zbjg and tszb_yn=:new.tszb_yn;
            EXCEPTION
            WHEN no_data_found THEN
              raise_application_error('-20002','[指标年月' || :new.tszb_yn || '尚未创建汇总表，不允许下达计划。]');
          end;
          if :new.tszbje>0 and v_hzbye_ck<:new.tszbje then
             raise_application_error('-20002','[出库机关' || v_ck_zbjg || '的指标余额('|| v_hzbye_ck ||')不足分配下发。]');
          end if;
          --出库机关指标中先行扣除（市局分配）
          update zb_tsjhzx_hzb set byxdjhe=nvl(byxdjhe,0)-:new.tszbje
             where zbjg_dm=v_ck_zbjg and tszb_yn=:new.tszb_yn;
        end if;
        update zb_tsjhzx_hzb set byxdjhe=nvl(byxdjhe,0)+:new.tszbje
           where zbjg_dm=:new.zbjg_dm and tszb_yn=:new.tszb_yn;
    end;
  end if;
end tru_zb_tsjhxd_wh;
/

prompt
prompt Creating trigger TRU_ZB_TSJHZX_HZB
prompt ==================================
prompt
CREATE OR REPLACE TRIGGER tru_zb_tsjhzx_hzb
  before update
  on ZB_TSJHZX_HZB
  for each row
declare

begin
  if updating('byxdjhe') or updating('syjzjhe') or updating('byzhtse') or updating('byybltse') then
--    PROC_ZB_TSJHZX_HZB_COMPUTE(:new.tszb_ny,:new.zbjg_dm);

    --本月计划总额
    :new.byjhze := :new.byxdjhe+:new.syjzjhe+:new.byzhtse;

    if :new.byybltse> 0 and :new.byybltse > :new.byjhze then
        raise_application_error('-20001','[' || :new.zbjg_dm||'指标计划余额不足，不能继续办理退税清单！]');
    end if;

    --本月计划余额
    :new.byjhye := :new.byjhze-:new.byybltse;


    --本月计划完成率
    :new.jhwcl := case when :new.byjhze=0 then 0 else round(:new.byybltse/:new.byjhze*100,2) end;

    --本年累计计划完成率
    :new.bnljjhwcl := case when :new.bnljxdjhe+:new.bnljzhtse+:new.byxdjhe+:new.byzhtse=0 then 0
		else round((:new.bnljbltse+:new.byybltse)/(:new.bnljxdjhe+:new.bnljzhtse+:new.byxdjhe+:new.byzhtse)*100,2) end;

  end if;
end tru_zb_tsjhzx_hzb;
/

